"\",\n    mirrors: null, modsList: null,\n    erId: \"\", erTok: \"\", erResult: null, erLoading: false, erError: \"\"\n  }\n};\nvar pollTimer = null;\n\n/* ---------- 数据层（localStorage 读写，叶子函数） ---------- */\nfunction loadState() {\n  try {\n    var raw = localStorage.getItem(LS_CFG);\n    state.config = raw ? mergeConfig(JSON.parse(raw)) : buildConfigFromEnv();\n  } catch (e) { state.config = buildConfigFromEnv(); }\n  try {\n    var t = localStorage.getItem(LS_TODOS);\n    state.todos = t ? JSON.parse(t) : null;\n  } catch (e) { state.todos = null; }\n  if (!state.todos) {\n    var now = Date.now(), D = 86400e3;\n    state.todos = [\n      { id: uid(), text: \"回复 T-2091 闪退工单\", createdAt: now - 2 * D, done: false },\n      { id: uid(), text: \"审核「动态光影增强 2.1.0」更新包\", createdAt: now - 3 * 3600e3, done: false },\n      { id: uid(), text: \"发布本周博客更新公告\", createdAt: now - 1 * 3600e3, done: false }\n    ];\n    saveTodos();\n  }\n}\n/* 数据映射规范化：结构无效（空对象/缺 metrics/list）一律回退页面内置默认，\n   防止设置面板保存过 {} 之类的脏映射导致「未取到列表数据」 */\nfunction normalizeAdvanced(id, adv) {\n  var ok = adv && typeof adv === \"object\" && !Array.isArray(adv) &&\n    Array.isArray(adv.metrics) && adv.metrics.length > 0 &&\n    adv.list && typeof adv.list.path === \"string\" && adv.list.path &&\n    Array.isArray(adv.list.columns) && adv.list.columns.length > 0;\n  return ok ? adv : (DEFAULT_MAPPING[id] || adv || null);\n}\n/* 兼容旧配置结构，缺失字段用页面内置配置补齐 */\nfunction mergeConfig(saved) {\n  var base = buildConfigFromEnv();\n  var cfg = Object.assign({}, base, saved || {});\n  cfg.services = base.services.map(function (bs) {\n    var found = null;\n    (saved.services || []).forEach(function (ss) { if (ss.id === bs.id) found = ss; });\n    if (!found) return bs;\n    var svc = Object.assign({}, bs, found);\n    svc.advanced = found.advanced || bs.advanced;\n    svc.advanced = normalizeAdvanced(svc.id, svc.advanced);\n    /* 迁移：wiki 旧演示映射 → 真实 API 结构（文章列表）；空 API 地址用内置配置补齐 */\n    if (svc.id === \"wiki\") {\n      var wm = svc.advanced && svc.advanced.metrics && svc.advanced.metrics[0];\n      if (wm && wm.path === \"data.stats.pages\") svc.advanced = DEFAULT_MAPPING.wiki;\n      if (!svc.baseUrl && (window.WB_ENV.SERVICES.wiki || {}).API) svc.baseUrl = window.WB_ENV.SERVICES.wiki.API;\n      if (!svc.url && (window.WB_ENV.SERVICES.wiki || {}).URL) svc.url = window.WB_ENV.SERVICES.wiki.URL;\n    }\n    /* 迁移：梦之韵四大服务接入 releases.camzy.uno —— 旧演示映射/空地址自动补齐 */\n    if ([\"downloads\", \"tickets\", \"mods\"].indexOf(svc.id) >= 0) {\n      var dm = svc.advanced && svc.advanced.metrics && svc.advanced.metrics[0];\n      if (dm && /^data\\.stats\\./.test(dm.path)) svc.advanced = DEFAULT_MAPPING[svc.id];\n      var envS = window.WB_ENV.SERVICES[svc.id] || {};\n      if (!svc.baseUrl && envS.API) svc.baseUrl = envS.API;\n      if (!svc.url && envS.URL) svc.url = envS.URL;\n    }\n    return svc;\n  });\n  if (typeof cfg.demoMode !== \"boolean\") cfg.demoMode = true;\n  cfg.pollMinutes = Number(cfg.pollMinutes) || 0;\n  return cfg;\n}\nfunction saveConfig() { try { localStorage.setItem(LS_CFG, JSON.stringify(state.config)); } catch (e) {} markDirty(); }\nfunction saveTodos() { try { localStorage.setItem(LS_TODOS, JSON.stringify(state.todos)); } catch (e) {} markDirty(); }\nfunction uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }\n\n/* ---------- 云同步（GitHub Contents API，仓库即数据库） ---------- */\nfunction syncEnv() {\n  return (window.WB_ENV && window.WB_ENV.SYNC) || { REPO: \"\", BRANCH: \"main\", PATH: \"data/state.json\", AUTO: false };\n}\nfunction syncToken() {\n  try { return localStorage.getItem(LS_SYNC_TOKEN) || \"\"; } catch (e) { return \"\"; }\n}\nfunction syncAutoOn() {\n  try {\n    var v = localStorage.getItem(LS_SYNC_AUTO);\n    if (v === null) return !!syncEnv().AUTO;\n    return v === \"1\";\n  } catch (e) { return false; }\n}\nfunction syncTokensOn() {\n  try { return localStorage.getItem(LS_SYNC_TOKENS) === \"1\"; } catch (e) { return false; }\n}\nfunction syncReady() { return !!(syncEnv().REPO && syncToken()); }\nfunction setSyncStatus(text) {\n  var el = document.getElementById(\"syncStatus\");\n  if (el) {\n    el.textContent = text + \"（\" + fmtTime(Date.now()) + \"）\";\n    try { localStorage.setItem(LS_LAST_SYNC, text); } catch (e) {}\n  }\n}\nfunction syncApiUrl() {\n  var s = syncEnv();\n  return \"https://api.github.com/repos/\" + s.REPO + \"/contents/\" + s.PATH + \"?ref=\" + s.BRANCH;\n}\nfunction b64Utf8Encode(str) { return btoa(utf8(str)); }\nfunction b64Utf8Decode(b64) {\n  try { return decodeURIComponent(escape(atob(String(b64).replace(/\\n/g, \"\")))); }\n  catch (e) { return atob(String(b64).replace(/\\n/g, \"\")); }\n}\nfunction syncHeaders(extra) {\n  var h = { \"Accept\": \"application/vnd.github+json\", \"Content-Type\": \"application/json\" };\n  h[\"Authorization\"] = \"Bearer \" + syncToken();\n  if (extra) { for (var k in extra) h[k] = extra[k]; }\n  return h;\n}\n/* 云端数据文件 → 本地存储的 JSON（content base64 / sha） */\nfunction fetchCloud() {\n  return fetch(syncApiUrl(), { headers: syncHeaders() }).then(function (res) {\n    if (res.status === 404) return { exists: false };\n    if (!res.ok) throw new Error(\"HTTP \" + res.status + (res.status === 401 ? \"（Token 无效或无权限）\" : res.status === 403 ? \"（权限不足或触发限流）\" : \"\"));\n    return res.json().then(function (j) { return { exists: true, sha: j.sha, json: JSON.parse(b64Utf8Decode(j.content)) }; });\n  });\n}\n/* 上传本地状态到云端（剥离敏感字段除非开启） */\nfunction buildSyncPayload() {\n  var cfg = JSON.parse(JSON.stringify(state.config));\n  if (!syncTokensOn()) cfg.services.forEach(function (s) { s.token = \"\"; });\n  return { type: \"wb-hub-cloud\", version: 3, savedAt: new Date().toISOString(), config: cfg, todos: state.todos };\n}\nfunction pushRemote(silent) {\n  if (!syncEnv().REPO) return Promise.resolve(false);\n  if (!syncToken()) {\n    if (!silent) showToast(\"请先在「设置 → 云同步」填写 GitHub Token\", \"err\");\n    return Promise.resolve(false);\n  }\n  setSyncStatus(\"上传中…\");\n  return fetchCloud().then(function (c) {\n    var body = {\n      message: \"sync: 工作台数据更新\",\n      branch: syncEnv().BRANCH,\n      content: b64Utf8Encode(JSON.stringify(buildSyncPayload(), null, 2))\n    };\n    if (c.exists) body.sha = c.sha;\n    return fetch(syncApiUrl(), { method: \"PUT\", headers: syncHeaders(), body: JSON.stringify(body) });\n  }).then(function (res) {\n    if (!res.ok) throw new Error(\"HTTP \" + res.status + (res.status === 409 ? \"（文件冲突，请重试）\" : res.status === 401 ? \"（Token 无效或无权限）\" : \"\"));\n    setSyncStatus(\"已上传到云端 ✓\");\n    if (!silent) showToast(\"已上传到云端\", \"good\");\n    return true;\n  }).catch(function (err) {\n    setSyncStatus(\"上传失败：\" + err.message);\n    if (!silent) showToast(\"上传失败：\" + err.message, \"err\");\n    return false;\n  });\n}\n/* 用云端数据合并到本地：配置覆盖（Token 保留本地值，除非开启同步），待办按 id 合并 */\nfunction applyCloud(cloud) {\n  if (!cloud || typeof cloud !== \"object\") return false;\n  var changed = false;\n  if (cloud.config && typeof cloud.config === \"object\") {\n    var c = cloud.config;\n    if (c.brand) { state.config.brand = c.brand; changed = true; }\n    if (typeof c.demoMode === \"boolean\") { state.config.demoMode = c.demoMode; changed = true; }\n    if (c.pollMinutes !== undefined) { state.config.pollMinutes = Number(c.pollMinutes) || 0; changed = true; }\n    var keepDemo = state.config.demoMode;\n    (c.services || []).forEach(function (cs) {\n      state.config.services.forEach(function (ls) {\n        if (ls.id !== cs.id) return;\n        [\"name\", \"url\", \"baseUrl\", \"authType\", \"headerName\"].forEach(function (k) {\n          if (cs[k] !== undefined && cs[k] !== \"\") ls[k] = cs[k];\n        });\n        if (syncTokensOn() && cs.token) ls.token = cs.token;\n        if (cs.advanced && (cs.advanced.metrics || cs.advanced.list || cs.advanced.todo)) ls.advanced = cs.advanced;\n        if (cs.enabled !== undefined) ls.enabled = cs.enabled;\n      });\n    });\n    state.config.demoMode = keepDemo;\n    if (typeof c.demoMode === \"boolean\") state.config.demoMode = c.demoMode;\n  }\n  if (Array.isArray(cloud.todos)) {\n    var ids = {};\n    state.todos.forEach(function (t) { ids[t.id] = true; });\n    cloud.todos.forEach(function (t) {\n      if (t && t.id && !ids[t.id]) { state.todos.push(t); ids[t.id] = true; changed = true; }\n    });\n  }\n  if (changed) {\n    applyingRemote = true;\n    saveConfig(); saveTodos();\n    applyingRemote = false;\n    refreshAll();\n  }\n  return changed;\n}\n/* 从云端拉取合并（silent=启动时自动，无弹窗） */\nfunction pullRemote(opts) {\n  opts = opts || {};\n  if (!syncEnv().REPO) return Promise.resolve(false);\n  if (!syncToken()) {\n    if (!opts.silent) showToast(\"请先在「设置 → 云同步」填写 GitHub Token\", \"err\");\n    return Promise.resolve(false);\n  }\n  setSyncStatus(opts.silent ? \"正在从云端同步…\" : \"拉取中…\");\n  return fetchCloud().then(function (c) {\n    if (!c.exists) {\n      setSyncStatus(\"云端暂无数据，可点「上传到云端」创建\");\n      if (!opts.silent) showToast(\"云端暂无数据\");\n      return false;\n    }\n    if (!opts.silent) {\n      return new Promise(function (resolve) {\n        confirmDialog(\"从云端恢复\", \"将用云端数据覆盖本地的品牌名/服务配置/映射，并把云端待办合并进来（本设备 Token 不受影响）。继续吗？\", function () {\n          resolve(applyCloud(c.json));\n        }, function () { resolve(false); });\n      }).then(function (ok) {\n        if (ok) { setSyncStatus(\"已从云端恢复 ✓\"); showToast(\"已从云端恢复\", \"good\"); }\n        return ok;\n      });\n    }\n    var changed = applyCloud(c.json);\n    setSyncStatus(changed ? \"已自动同步云端数据 ✓\" : \"云端已是最新 ✓\");\n    return changed;\n  }).catch(function (err) {\n    setSyncStatus(\"同步失败：\" + err.message);\n    if (!opts.silent) showToast(\"拉取失败：\" + err.message, \"err\");\n    return false;\n  });\n}\n/* 本地变更 → 后端模式防抖推 D1 / 本地模式防抖推 GitHub */\nvar dirtyTimer = null, serverDirtyTimer = null, applyingRemote = false;\nfunction markDirty() {\n  if (applyingRemote) return;\n  if (RUNTIME.mode === \"server\") {\n    if (!sessionToken()) return;\n    if (serverDirtyTimer) clearTimeout(serverDirtyTimer);\n    serverDirtyTimer = setTimeout(function () { pushServerState(true); }, 800);\n    return;\n  }\n  if (!syncAutoOn() || !syncReady()) return;\n  if (dirtyTimer) clearTimeout(dirtyTimer);\n  setSyncStatus(\"有未上传的本地变更…\");\n  dirtyTimer = setTimeout(function () { pushRemote(true); }, 5000);\n}\n\n/* ---------- 计算层（只读，无渲染、无副作用） ---------- */\nfunction getPath(obj, path) {\n  if (!path || typeof path !== \"string\") return undefined;\n  var parts = path.replace(/\\[(\\d+)\\]/g, \".$1\").split(\".\").filter(Boolean);\n  var cur = obj;\n  for (var i = 0; i < parts.length; i++) {\n    if (cur == null) return undefined;\n    cur = cur[parts[i]];\n  }\n  return cur;\n}\nfunction fmtNum(v) {\n  if (v === undefined || v === null || v === \"\") return \"—\";\n  if (typeof v === \"number\") {\n    if (isNaN(v)) return \"—\";\n    return v >= 100000 ? (v / 10000).toFixed(1).replace(/\\.0$/, \"\") + \"w\" : v.toLocaleString(\"zh-CN\");\n  }\n  return String(v);\n}\nfunction fmtTime(v) {\n  if (v === undefined || v === null || v === \"\") return \"—\";\n  var d = new Date(typeof v === \"number\" ? v : String(v));\n  if (isNaN(d.getTime())) return String(v);\n  var p = function (n) { return n < 10 ? \"0\" + n : \"\" + n; };\n  return (d.getMonth() + 1) + \"月\" + d.getDate() + \"日 \" + p(d.getHours()) + \":\" + p(d.getMinutes());\n}\nfunction fmtBytes(v) {\n  var n = Number(v);\n  if (!isFinite(n) || n < 0) return \"—\";\n  if (n >= 1073741824) return (n / 1073741824).toFixed(2) + \" GB\";\n  if (n >= 1048576) return (n / 1048576).toFixed(1) + \" MB\";\n  if (n >= 1024) return (n / 1024).toFixed(1) + \" KB\";\n  return n + \" B\";\n}\nfunction startOfToday() { var d = new Date(); d.setHours(0, 0, 0, 0); return d.getTime(); }\nfunction getApiData(svc) {\n  var c = state.api[svc.id];\n  if (c && c.ok) return { data: c.data, source: \"api\" };\n  if (state.config.demoMode) return { data: state.demo[svc.id], source: \"demo\" };\n  return null;\n}\nfunction computeStatus(svc) {\n  var c = state.api[svc.id];\n  if (c && c.loading) return \"loading\";\n  if (svc.baseUrl && c && c.ok) return \"ok\";\n  if (svc.baseUrl && c && !c.ok) return state.config.demoMode ? \"demo\" : \"error\";\n  return state.config.demoMode ? \"demo\" : \"idle\";\n}\nvar STATUS_TEXT = { ok: \"已连接\", demo: \"演示数据\", error: \"连接失败\", idle: \"未接入\", loading: \"同步中\" };\nfunction badgeFor(v) {\n  var map = {\n    \"critical\": \"b-red\", \"严重\": \"b-red\", \"高\": \"b-red\", \"紧急\": \"b-red\", \"未处理\": \"b-red\", \"连接失败\": \"b-red\",\n    \"new\": \"b-red\", \"待处理\": \"b-orange\", \"待审核\": \"b-orange\", \"warning\": \"b-orange\", \"中\": \"b-orange\", \"顺延\": \"b-orange\", \"演示数据\": \"b-orange\",\n    \"处理中\": \"b-blue\", \"进行中\": \"b-blue\", \"同步中\": \"b-blue\", \"auto\": \"b-blue\", \"AI已回复\": \"b-blue\", \"processing\": \"b-blue\", \"queued\": \"b-blue\",\n    \"已完成\": \"b-green\", \"已发布\": \"b-green\", \"已处理\": \"b-green\", \"已解决\": \"b-green\", \"已连接\": \"b-green\", \"replied\": \"b-green\", \"done\": \"b-green\",\n    \"未接入\": \"b-gray\", \"closed\": \"b-gray\", \"已关闭\": \"b-gray\"\n  };\n  return map[String(v)] || \"b-gray\";\n}\n/* 工单/报告状态 → 中文显示 */\nfunction statusText(v) {\n  return { \"new\": \"新工单\", \"auto\": \"AI已回复\", \"replied\": \"已回复\", \"closed\": \"已关闭\",\n    \"queued\": \"排队中\", \"processing\": \"分析中\", \"done\": \"分析完成\", \"error\": \"分析失败\" }[String(v)] || String(v);\n}\n\n/* 「今天要处理」聚合：本地待办 + 服务待处理项提取 */\nfunction collectTodayItems() {\n  var items = [], now = Date.now();\n  state.todos.forEach(function (t) {\n    if (t.done) return;\n    var overdue = t.createdAt < startOfToday();\n    items.push({\n      kind: \"todo\", id: t.id,\n      title: t.text,\n      meta: overdue ? \"顺延自 \" + fmtTime(t.createdAt) : \"快速待办 · \" + fmtTime(t.createdAt),\n      level: overdue ? \"warn\" : \"today\"\n    });\n  });\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    var todo = svc.advanced && svc.advanced.todo;\n    if (!todo || !todo.listPath) return;\n    var src = getApiData(svc);\n    if (!src) return;\n    var list = getPath(src.data, todo.listPath);\n    if (!Array.isArray(list)) return;\n    var pendingVals = String(todo.pendingValue || \"\").split(\",\").map(function (s) { return s.trim(); }).filter(Boolean);\n    var count = 0, shown = 0;\n    list.forEach(function (it) {\n      var st = getPath(it, todo.statusPath);\n      if (st === undefined) return;\n      if (pendingVals.indexOf(String(st)) === -1) return;\n      count++;\n      if (shown >= 6) return;\n      shown++;\n      var dv = todo.datePath ? getPath(it, todo.datePath) : null;\n      var d = dv !== null && dv !== undefined ? new Date(typeof dv === \"number\" ? dv : String(dv)) : null;\n      var valid = d && !isNaN(d.getTime());\n      var overdue = valid && (now - d.getTime()) > 24 * 3600e3;\n      items.push({\n        kind: \"svc\", svcId: svc.id,\n        title: String(getPath(it, todo.titlePath) || \"(未命名)\"),\n        meta: svc.name + \" · \" + statusText(st) + (valid ? \" · \" + fmtTime(dv) : \"\"),\n        level: overdue ? \"overdue\" : \"today\"\n      });\n    });\n    if (count > 6) {\n      items.push({ kind: \"more\", svcId: svc.id, title: \"还有 \" + (count - 6) + \" 条待处理…\", meta: \"前往「\" + svc.name + \"」查看全部\", level: \"today\" });\n    }\n  });\n  var order = { overdue: 0, warn: 1, today: 2 };\n  items.sort(function (a, b) { return order[a.level] - order[b.level]; });\n  return items;\n}\n\n/* ---------- API 层 ---------- */\nfunction buildHeaders(svc) {\n  var h = {};\n  if (svc.authType === \"bearer\" && svc.token) h[\"Authorization\"] = \"Bearer \" + svc.token;\n  if (svc.authType === \"header\" && svc.token) h[svc.headerName || \"X-API-Key\"] = svc.token;\n  return h;\n}\nfunction callServiceApi(svc) {\n  var ctrl = new AbortController();\n  var timer = setTimeout(function () { ctrl.abort(); }, 10000);\n  var p;\n  if (RUNTIME.mode === \"server\") {\n    /* 后端网关模式：由 Worker 读取 D1 中的服务配置并转发，前端不经手 Token，无 CORS 问题 */\n    p = fetch(\"api/proxy/\" + svc.id, { headers: apiHeaders(), signal: ctrl.signal })\n      .then(function (res) { if (!res.ok) throw new Error(\"HTTP \" + res.status); return res.json(); });\n  } else {\n    p = fetch(svc.baseUrl, { headers: buildHeaders(svc), signal: ctrl.signal })\n      .then(function (res) {\n        if (!res.ok) throw new Error(\"HTTP \" + res.status);\n        return res.json();\n      });\n  }\n  return p.finally(function () { clearTimeout(timer); });\n}\nfunction fetchService(id, silent) {\n  var svc = null;\n  state.config.services.forEach(function (s) { if (s.id === id) svc = s; });\n  if (!svc || !svc.enabled || !svc.baseUrl) return Promise.resolve();\n  state.api[id] = { ok: false, loading: true, ts: Date.now() };\n  if (!silent) refreshAll();\n  return callServiceApi(svc)\n    .then(function (data) { state.api[id] = { ok: true, data: data, ts: Date.now() }; })\n    .catch(function (err) {\n      var msg = (err && err.name === \"AbortError\") ? \"请求超时（10s）\" : (err && err.message) || \"请求失败\";\n      state.api[id] = { ok: false, error: msg + \"（可能为 CORS 拦截或地址/认证有误）\", ts: Date.now() };\n    })\n    .then(function () { refreshAll(); });\n}\nfunction fetchAll(silent) {\n  var jobs = [];\n  state.config.services.forEach(function (s) {\n    if (s.enabled && s.baseUrl) jobs.push(fetchService(s.id, silent));\n  });\n  return Promise.all(jobs);\n}\nfunction setupPoll() {\n  if (pollTimer) { clearInterval(pollTimer); pollTimer = null; }\n  var m = Number(state.config.pollMinutes) || 0;\n  if (m > 0) pollTimer = setInterval(function () { fetchAll(true); }, m * 60000);\n}\n\n/* ---------- 主题 ---------- */\nfunction applyTheme() {\n  var t = \"auto\";\n  try { t = localStorage.getItem(LS_THEME) || \"auto\"; } catch (e) {}\n  var dark = t === \"dark\" || (t === \"auto\" && window.matchMedia && window.matchMedia(\"(prefers-color-scheme: dark)\").matches);\n  document.documentElement.setAttribute(\"data-theme\", dark ? \"dark\" : \"light\");\n  var btn = document.getElementById(\"btnTheme\");\n  if (btn) btn.innerHTML = ic(dark ? \"sun\" : \"moon\");\n  var meta = document.querySelector('meta[name=\"theme-color\"]');\n  if (meta) meta.setAttribute(\"content\", dark ? \"#121a2b\" : \"#ffffff\");\n}\nfunction cycleTheme() {\n  var cur = \"auto\";\n  try { cur = localStorage.getItem(LS_THEME) || \"auto\"; } catch (e) {}\n  var next = cur === \"auto\" ? \"light\" : cur === \"light\" ? \"dark\" : \"auto\";\n  try { localStorage.setItem(LS_THEME, next); } catch (e) {}\n  applyTheme();\n  showToast(\"主题：\" + (next === \"auto\" ? \"跟随系统\" : next === \"light\" ? \"浅色\" : \"深色\"));\n}\n\n/* ---------- 渲染层（叶子：只读 state 与 DOM，互不调用） ---------- */\nvar $ = function (id) { return document.getElementById(id); };\nfunction esc(s) {\n  return String(s === undefined || s === null ? \"\" : s)\n    .replace(/&/g, \"&amp;\").replace(/</g, \"&lt;\").replace(/>/g, \"&gt;\")\n    .replace(/\"/g, \"&quot;\").replace(/'/g, \"&#39;\");\n}\n\nfunction renderBrand() {\n  $(\"brandName\").textContent = state.config.brand || \"聚合工作台\";\n  document.title = state.config.brand || \"聚合工作台\";\n  var m = document.querySelector('meta[name=\"apple-mobile-web-app-title\"]');\n  if (m) m.setAttribute(\"content\", state.config.brand || \"工作台\");\n}\n\nfunction renderNav() {\n  var html = '<button class=\"chip' + (state.view === \"overview\" ? \" active\" : \"\") + '\" data-action=\"goto\" data-view=\"overview\">' + ic(\"hub\", 15) + \"总览</button>\";\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    html += '<button class=\"chip' + (state.view === svc.id ? \" active\" : \"\") + '\" data-action=\"goto\" data-view=\"' + svc.id + '\">' + ic(svc.icon, 15) + esc(svc.name) + \"</button>\";\n  });\n  $(\"mainNav\").innerHTML = html;\n}\n\nfunction renderHeaderStatus() {\n  var ok = 0, demo = 0, err = 0, idle = 0;\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    var st = computeStatus(svc);\n    if (st === \"ok\") ok++;\n    else if (st === \"demo\") demo++;\n    else if (st === \"error\") err++;\n    else idle++;\n  });\n  var parts = [];\n  if (ok) parts.push(ok + \" 在线\");\n  if (demo) parts.push(demo + \" 演示\");\n  if (err) parts.push(err + \" 失败\");\n  if (idle) parts.push(idle + \" 未接入\");\n  var dotCls = err ? \"error\" : ok ? \"ok\" : demo ? \"demo\" : \"idle\";\n  $(\"globalStatus\").innerHTML = '<span class=\"dot ' + dotCls + '\"></span>' + esc(parts.join(\" · \") || \"无服务\");\n}\n\nfunction renderBanner() {\n  var show = false;\n  if (state.config.demoMode && !state.config.bannerClosed) {\n    state.config.services.forEach(function (svc) {\n      if (svc.enabled && (!svc.baseUrl || (state.api[svc.id] && !state.api[svc.id].ok && !state.api[svc.id].loading))) show = true;\n    });\n  }\n  $(\"demoBanner\").classList.toggle(\"hidden\", !show);\n}\n\nfunction renderToday() {\n  var items = collectTodayItems();\n  var openCount = items.filter(function (i) { return i.kind !== \"more\"; }).length;\n  var pill = $(\"todayCount\");\n  pill.textContent = String(openCount);\n  pill.classList.toggle(\"zero\", openCount === 0);\n  $(\"todaySection\").classList.toggle(\"closed\", !state.todayOpen);\n  $(\"todayBody\").classList.toggle(\"hidden\", !state.todayOpen);\n\n  var html = \"\";\n  if (!items.length) {\n    html = '<div class=\"empty\">' + ic(\"check\", 42) + '<div>今日无待办，一切尽在掌握</div></div>';\n  } else {\n    items.forEach(function (it) {\n      var actions = \"\";\n      if (it.kind === \"todo\") {\n        actions = '<button class=\"btn small\" data-action=\"done-todo\" data-id=\"' + it.id + '\" title=\"标记完成\">' + ic(\"check\", 14) + \"完成</button>\" +\n                  '<button class=\"btn small ghost\" data-action=\"del-todo\" data-id=\"' + it.id + '\" title=\"删除\">' + ic(\"x\", 14) + \"</button>\";\n      } else {\n        actions = '<button class=\"btn small\" data-action=\"goto\" data-view=\"' + it.svcId + '\">去处理' + ic(\"chevron\", 14) + \"</button>\";\n      }\n      html += '<div class=\"t-item ' + it.level + '\"><span class=\"t-dot\"></span>' +\n        '<div class=\"t-main\"><div class=\"t-title\">' + esc(it.title) + '</div><div class=\"t-meta\">' + esc(it.meta) + \"</div></div>\" +\n        '<div class=\"t-actions\">' + actions + \"</div></div>\";\n    });\n  }\n  $(\"todayList\").innerHTML = html;\n}\n\nfunction renderOverview() {\n  var enabled = state.config.services.filter(function (s) { return s.enabled; });\n  if (!enabled.length) {\n    $(\"viewOverview\").innerHTML = '<div class=\"sec-title\">' + ic(\"hub\", 17) + \"服务总览</div>\" +\n      '<div class=\"card\" style=\"padding:36px 20px;text-align:center;color:var(--text2)\">' + ic(\"gear\", 36) +\n      '<div style=\"margin-top:10px;font-weight:700;color:var(--text)\">所有服务均已停用</div>' +\n      '<div style=\"font-size:13px;margin-top:4px\">前往设置重新启用你需要的服务</div>' +\n      '<button class=\"btn primary\" style=\"margin-top:15px\" data-action=\"open-settings\">打开设置</button></div>';\n    $(\"viewOverview\").classList.remove(\"hidden\");\n    return;\n  }\n  var html = '<div class=\"sec-title\">' + ic(\"hub\", 17) + '服务总览<span class=\"sub\">点击卡片进入详情</span></div><div class=\"ov-grid\">';\n  state.config.services.forEach(function (svc) {\n    if (!svc.enabled) return;\n    var st = computeStatus(svc);\n    var src = getApiData(svc);\n    var metricsHtml = \"\";\n    var mets = (svc.advanced && svc.advanced.metrics) || [];\n    for (var i = 0; i < 3; i++) {\n      var m = mets[i];\n      if (!m) { metricsHtml += '<div class=\"ov-metric\"><div class=\"v\">—</div><div class=\"l\">&nbsp;</div></div>'; continue; }\n      var v = src ? getPath(src.data, m.path) : undefined;\n      metricsHtml += '<div class=\"ov-metric\"><div class=\"v\">' + esc(fmtNum(v)) + (m.unit ? '<span class=\"u\">' + esc(m.unit) + \"</span>\" : \"\") +\n        '</div><div class=\"l\">' + esc(m.label) + \"</div></div>\";\n    }\n    var linkBtn = svc.url\n      ? '<a class=\"btn small\" href=\"' + esc(svc.url) + '\" target=\"_blank\" rel=\"noopener\" onclick=\"event.stopPropagation()\">' + ic(\"out\", 14) + \"打开</a>\"\n      : \"\";\n    html += '<div class=\"card ov-card svc-c-' + svc.id + '\" data-action=\"goto\" data-view=\"' + svc.id + '\">' +\n      '<div class=\"ov-head\"><span class=\"ov-ico\">' + ic(svc.icon) + '</span><h3>' + esc(svc.name) + \"</h3>\" +\n      '<span class=\"dot ' + st + '\" title=\"' + STATUS_TEXT[st] + '\"></span></div>' +\n      '<div class=\"ov-metrics\">' + metricsHtml + \"</div>\" +\n      '<div class=\"ov-foot\"><span class=\"badge ' + badgeFor(STATUS_TEXT[st]) + '\">' + STATUS_TEXT[st] + \"</span>\" + linkBtn +\n      '<span class=\"arrow\">' + ic(\"chevron\", 16) + \"</span></div></div>\";\n  });\n  html += \"</div>\";\n  $(\"viewOverview\").innerHTML = html;\n  $(\"viewOverview\").classList.toggle(\"hidden\", state.view !== \"overview\");\n}\n\nfunction renderService() {\n  var box = $(\"viewService\");\n  var svc = null;\n  state.config.services.forEach(function (s) { if (s.id === state.view) svc = s; });\n  if (!svc) { box.innerHTML = \"\"; box.classList.add(\"hidden\"); return; }\n  box.classList.remove(\"hidden\");\n\n  var st = computeStatus(svc);\n  var src = getApiData(svc);\n  var loading = state.api[svc.id] && state.api[svc.id].loading;\n\n  var head = '<div class=\"svc-head svc-c-' + svc.id + '\"><span class=\"ov-ico\">' + ic(svc.icon) + \"</span><h2>\" + esc(svc.name) + \"</h2>\" +\n    '<span class=\"badge ' + badgeFor(STATUS_TEXT[st]) + '\">' + STATUS_TEXT[st] + \"</span>\" +\n    '<span class=\"grow\"></span>' +\n    (svc.url ? '<a class=\"btn small\" href=\"' + esc(svc.url) + '\" target=\"_blank\" rel=\"noopener\">' + ic(\"out\", 14) + \"打开服务</a>\" : \"\") +\n    '<button class=\"btn small\" data-action=\"svc-refresh\" data-svc=\"' + svc.id + '\">' + ic(\"refresh\", 14) + \"刷新</button>\" +\n    '<button class=\"btn small ghost\" data-action=\"open-settings\">' + ic(\"gear\", 14) + \"配置</button>\" +\n    (svc.desc ? '<div class=\"desc\">' + esc(svc.desc) + \"</div>\" : \"\") + \"</div>\";\n\n  var body = \"\";\n  if (state.api[svc.id] && !state.api[svc.id].ok && !state.api[svc.id].loading && svc.baseUrl && !state.config.demoMode) {\n    body += '<div class=\"err-box\">' + ic(\"errors\", 16) + \"<span>API 请求失败：\" + esc(state.api[svc.id].error || \"\") + \"</span>\" +\n      '<button class=\"btn\" data-action=\"svc-refresh\" data-svc=\"' + svc.id + '\">重试</button>' +\n      '<button class=\"btn ghost\" data-action=\"open-settings\">检查配置</button></div>';\n  }\n  if (loading) {\n    body += '<div class=\"metric-grid\">' + '<div class=\"card metric-card\"><div class=\"v\">…</div><div class=\"l\">正在同步</div></div></div>';\n  } else if (!src) {\n    body += '<div class=\"card\" style=\"padding:38px 20px;text-align:center;color:var(--text2)\">' + ic(\"gear\", 36) +\n      '<div style=\"margin-top:10px;font-weight:700;color:var(--text)\">尚未接入 API</div>' +\n      '<div style=\"font-size:13px;margin-top:4px\">在设置中填入该服务的 API 地址与 Token，即可在此展示真实数据</div>' +\n      '<button class=\"btn primary\" style=\"margin-top:15px\" data-action=\"open-settings\">去接入</button></div>';\n  } else {\n    var mets = (svc.advanced && svc.advanced.metrics) || [];\n    if (mets.length) {\n      body += '<div class=\"metric-grid\">';\n      mets.forEach(function (m) {\n        var v = getPath(src.data, m.path);\n        var mv = m.format === \"time\" ? fmtTime(v) : fmtNum(v);\n        var warn = /未处理|逾期|待处理|待审核|严重|失败/.test(m.label || \"\") && typeof v === \"number\" && v > 0;\n        body += '<div class=\"card metric-card' + (warn ? \" warn\" : \"\") + '\"><div class=\"v\">' + esc(mv) +\n          (m.unit ? '<span class=\"u\">' + esc(m.unit) + \"</span>\" : \"\") + '</div><div class=\"l\">' + esc(m.label) + \"</div></div>\";\n      });\n      body += \"</div>\";\n    }\n    var list = svc.advanced && svc.advanced.list;\n    var rows = list ? getPath(src.data, list.path) : null;\n    if (Array.isArray(rows) && rows.length && list.columns && list.columns.length) {\n      var t = \"<table><thead><tr>\";\n      list.columns.forEach(function (c) { t += \"<th>\" + esc(c.title) + \"</th>\"; });\n      t += \"</tr></thead><tbody>\";\n      rows.slice(0, 50).forEach(function (row) {\n        t += \"<tr>\";\n        list.columns.forEach(function (c) {\n          var v = getPath(row, c.path);\n          var lab = ' data-label=\"' + esc(c.title) + '\"';\n          var cell;\n          if (c.format === \"num\") cell = '<td class=\"num\"' + lab + \">\" + esc(fmtNum(v)) + \"</td>\";\n          else if (c.format === \"bytes\") cell = '<td class=\"num\"' + lab + \">\" + esc(fmtBytes(v)) + \"</td>\";\n          else if (c.format === \"badge\") { var bv = Array.isArray(v) ? v.join(\"、\") : v; bv = statusText(bv); cell = \"<td\" + lab + '><span class=\"badge ' + badgeFor(bv) + '\">' + esc(bv === undefined || bv === null || bv === \"\" ? \"—\" : bv) + \"</span></td>\"; }\n          else if (c.format === \"time\") cell = \"<td\" + lab + \">\" + esc(fmtTime(v)) + \"</td>\";\n          else cell = \"<td\" + lab + \">\" + esc(v === undefined || v === null || v === \"\" ? \"—\" : v) + \"</td>\";\n          t += cell;\n        });\n        t += \"</tr>\";\n      });\n      t += \"</tbody></table>\";\n      body += '<div class=\"tbl-wrap card svc-c-' + svc.id + '\">' + t +\n        (rows.length > 50 ? '<div class=\"note\">仅显示前 50 条，共 ' + rows.length + \" 条</div>\" : \"\") +\n        (src.source === \"demo\" ? '<div class=\"note\">当前为演示数据 · 接入真实 API 后自动替换</div>' : \"\") +\n        \"</div>\";\n    } else {\n      body += '<div class=\"card\" style=\"padding:28px;text-align:center;color:var(--text2)\">' +\n        (src.source === \"demo\" ? \"演示数据为空\" : \"未取到列表数据\") +\n        '<div style=\"font-size:12px;margin-top:4px\">请检查映射中 list.path 是否指向数组字段</div></div>';\n    }\n  }\n  if (svc.id === \"wiki\" && svc.baseUrl && !loading) body += wikiAdminHtml(svc, src);\n  if (!loading) {\n    if (svc.id === \"tickets\") body += mzyTicketAdminHtml();\n    if (svc.id === \"mods\") body += mzyModsAdminHtml();\n    if (svc.id === \"downloads\") body += mzyDlInfoHtml(svc);\n    if (svc.id === \"errors\") body += mzyErQueryHtml();\n  }\n  box.innerHTML = head + body;\n}\n\n/* ---------- Wiki 内容管理（POST/PUT/DELETE 写回 GitHub 仓库，触发 CI 自动部署） ---------- */\nfunction wikiSvc() {\n  var s = null;\n  state.config.services.forEach(function (x) { if (x.id === \"wiki\") s = x; });\n  return s;\n}\nfunction wikiArticles(src) {\n  if (!src || !src.data) return [];\n  var rows = getPath(src.data, \"data\");\n  return Array.isArray(rows) ? rows : [];\n}\nfunction wikiFormDefault() {\n  var d = new Date();\n  var p = function (n) { return n < 10 ? \"0\" + n : \"\" + n; };\n  return { slug: \"\", title: \"\", group: \"\", tags: \"\", date: d.getFullYear() + \"-\" + p(d.getMonth() + 1) + \"-\" + p(d.getDate()), body: \"\" };\n}\n/* 纯模板：由 renderService 组合输出，无副作用、不触发其他渲染 */\nfunction wikiAdminHtml(svc, src) {\n  var w = state.wiki, f = w.form || wikiFormDefault();\n  var arts = wikiArticles(src);\n  var local = RUNTIME.mode !== \"server\";\n  var head = '<div class=\"card wiki-admin\"><div class=\"wa-head\">' + ic(\"edit\", 16) + \"<b>Wiki 内容管理</b>\" +\n    '<span class=\"badge ' + (local ? \"b-gray\" : \"b-green\") + '\">' + (local ? \"本地直连\" : \"网关写入\") + \"</span>\" +\n    '<span class=\"grow\"></span>' +\n    '<button class=\"btn small' + (w.mode === \"new\" ? \" primary\" : \"\") + '\" data-action=\"wiki-new\">＋ 新建文章</button></div>' +\n    '<div class=\"note\">写操作将提交到 Wiki 仓库并触发自动重新部署；列表为演示数据时请勿执行写操作。' +\n    (local ? \"本地模式需在设置中为 Wiki 配置 Bearer 写密钥（Worker 版由服务端注入，无需配置）。\" : \"\") + \"</div>\";\n  var opts = '<option value=\"\">— 选择要编辑/删除的文章 —</option>';\n  arts.forEach(function (a) {\n    var link = a.link || \"\";\n    opts += '<option value=\"' + esc(link) + '\"' + (w.link === link ? \" selected\" : \"\") + \">\" + esc((a.title || link) + (a.date ? \"（\" + a.date + \"）\" : \"\")) + \"</option>\";\n  });\n  var bodyHtml = '<div class=\"wa-form\">' +\n    '<label class=\"wa-label\">编辑已有文章（选中后可修改 / 删除）</label><select class=\"wa-input\" data-wfield=\"link\">' + opts + \"</select>\" +\n    (w.mode === \"new\" ? '<div class=\"wa-grid\"><div><label class=\"wa-label\">路径 slug <i>*</i></label><input class=\"wa-input\" data-wfield=\"slug\" placeholder=\"如 posts/my-note\" value=\"' + esc(f.slug) + '\"></div>' +\n      '<div><label class=\"wa-label\">日期</label><input class=\"wa-input\" type=\"date\" data-wfield=\"date\" value=\"' + esc(f.date) + '\"></div></div>' : \"\") +\n    '<div class=\"wa-grid\"><div><label class=\"wa-label\">标题</label><input class=\"wa-input\" data-wfield=\"title\" value=\"' + esc(f.title) + '\"></div>' +\n      '<div><label class=\"wa-label\">栏目</label><input class=\"wa-input\" data-wfield=\"group\" placeholder=\"如 使用指南\" value=\"' + esc(f.group) + '\"></div></div>' +\n    '<label class=\"wa-label\">标签（逗号分隔）</label><input class=\"wa-input\" data-wfield=\"tags\" placeholder=\"教程, 入门\" value=\"' + esc(f.tags) + '\">' +\n    '<label class=\"wa-label\">正文 Markdown' + (w.mode === \"edit\" ? \"（留空 = 不修改正文）\" : \"\") + '</label>' +\n    '<textarea class=\"wa-input\" rows=\"7\" data-wfield=\"body\" placeholder=\"# 标题&#10;&#10;正文…\">' + esc(f.body) + \"</textarea>\" +\n    '<div class=\"wa-actions\">' +\n    '<button class=\"btn primary\" data-action=\"wiki-submit\">' + (w.mode === \"edit\" ? \"保存修改\" : \"创建文章\") + \"</button>\" +\n    (w.mode === \"edit\" ? '<button class=\"btn danger\" data-action=\"wiki-del\">删除这篇文章</button><button class=\"btn ghost\" data-action=\"wiki-cancel\">退出编辑</button>' : \"\") +\n    \"</div></div>\";\n  return head + bodyHtml + \"</div>\";\n}\n/* 写请求：server 走网关（服务端注入 WRITE_KEY），local 直连（需本机配置密钥） */\nfunction wikiWrite(method, path, bodyObj) {\n  var svc = wikiSvc();\n  var body = bodyObj === null ? undefined : JSON.stringify(bodyObj);\n  var p;\n  if (RUNTIME.mode === \"server\") {\n    p = fetch(\"api/proxy/wiki\" + path, { method: method, headers: apiHeaders(), body: body });\n  } else {\n    if (!svc || svc.authType !== \"bearer\" || !svc.token) {\n      return Promise.reject(new Error(\"本地模式需写密钥：设置 → Wiki → 认证选 Bearer 并填入 WRITE_KEY（Worker 版无需配置）\"));\n    }\n    var h = buildHeaders(svc);\n    h[\"Content-Type\"] = \"application/json\";\n    p = fetch(svc.baseUrl.replace(/\\/+$/, \"\") + path, { method: method, headers: h, body: body });\n  }\n  return p.then(function (r) {\n    return r.json().then(function (j) { return { status: r.status, j: j }; });\n  }).then(function (res) {\n    if (res.status >= 400 || !res.j || res.j.code !== 0) throw new Error((res.j && res.j.msg) || \"HTTP \" + res.status);\n    return res.j;\n  });\n}\nfunction wikiStartEdit(link) {\n  state.wiki.link = link || \"\";\n  state.wiki.mode = \"edit\";\n  if (!link) { state.wiki.form = wikiFormDefault(); refreshAll(); return; }\n  var art = null;\n  wikiArticles(getApiData(wikiSvc())).forEach(function (a) { if ((a.link || \"\") === link) art = a; });\n  state.wiki.form = {\n    slug: link.replace(/^\\/+|\\/+$/g, \"\"),\n    title: art ? (art.title || \"\") : \"\",\n    group: art ? (art.group || \"\") : \"\",\n    tags: art && Array.isArray(art.tags) ? art.tags.join(\", \") : \"\",\n    date: art ? (art.date || \"\") : \"\",\n    body: \"\"\n  };\n  refreshAll();\n}\n/* 事件层：读取 DOM 表单 → 确认 → 写请求 → 清表单 + 刷新列表 */\nfunction wikiSubmit() {\n  var f = state.wiki.form || wikiFormDefault();\n  var svc = wikiSvc();\n  if (!svc || !svc.baseUrl) { showToast(\"请先在设置中接入 Wiki API 地址\", \"err\"); return; }\n  var edit = state.wiki.mode === \"edit\" && state.wiki.link;\n  if (!edit && !String(f.slug || \"\").trim()) { showToast(\"新建文章必须填写 slug（如 posts/my-note）\", \"err\"); return; }\n  var payload = { title: String(f.title || \"\").trim() };\n  if (!edit) payload.slug = String(f.slug || \"\").trim();  // POST 新建必填 slug；PUT 按 URL 定位无需 slug\n  if (String(f.body || \"\").length) payload.body = f.body;\n  if (String(f.group || \"\").trim()) payload.categories = [f.group.trim()];\n  if (String(f.tags || \"\").trim()) payload.tags = f.tags.split(/[,，]/).map(function (s) { return s.trim(); }).filter(Boolean);\n  if (String(f.date || \"\").trim()) payload.date = f.date.trim();\n  var slug = edit ? state.wiki.link.replace(/^\\/+|\\/+$/g, \"\") : \"\";\n  confirmDialog(edit ? \"保存修改\" : \"创建文章\",\n    edit ? \"将向 Wiki 仓库提交更新（\" + (payload.body ? \"包含正文覆盖\" : \"仅元数据\") + \"），并触发自动重新部署。确定提交？\"\n         : \"将向 Wiki 仓库新建 docs/\" + slug + \".md，并触发自动重新部署。确定创建？\",\n    function () {\n      showToast(\"正在提交，请稍候…\");\n      wikiWrite(edit ? \"PUT\" : \"POST\", edit ? \"/\" + slug : \"\", payload).then(function (j) {\n        state.wiki = { mode: \"new\", link: \"\", form: wikiFormDefault() };\n        refreshAll();\n        fetchService(\"wiki\", true);\n        showToast(\"已提交：\" + (j.msg || \"成功\") + \"，CI 部署中\", \"good\");\n      }).catch(function (err) { showToast(\"提交失败：\" + err.message, \"err\"); });\n    });\n}\nfunction wikiDelete() {\n  if (state.wiki.mode !== \"edit\" || !state.wiki.link) { showToast(\"请先选择要删除的文章\", \"err\"); return; }\n  var slug = state.wiki.link.replace(/^\\/+|\\/+$/g, \"\");\n  confirmDialog(\"删除文章\", \"将向 Wiki 仓库提交删除 docs/\" + slug + \".md，此操作不可撤销。确定删除？\", function () {\n    showToast(\"正在删除…\");\n    wikiWrite(\"DELETE\", \"/\" + slug, null).then(function (j) {\n      state.wiki = { mode: \"new\", link: \"\", form: wikiFormDefault() };\n      refreshAll();\n      fetchService(\"wiki\", true);\n      showToast(\"已删除：\" + (j.msg || \"成功\") + \"，CI 部署中\", \"good\");\n    }).catch(function (err) { showToast(\"删除失败：\" + err.message, \"err\"); });\n  });\n}\nfunction wikiSyncForm(e) {\n  var el = e.target.closest ? e.target.closest(\"[data-wfield]\") : null;\n  if (!el) return;\n  var field = el.getAttribute(\"data-wfield\");\n  if (field === \"link\") { wikiStartEdit(el.value); return; }\n  if (!state.wiki.form) state.wiki.form = wikiFormDefault();\n  state.wiki.form[field] = el.value;\n}\n\n/* ---------- 梦之韵模组包发布系统（releases.camzy.uno）管理模块 ----------\n   读：网关转发公开接口；写：网关注入 D1 中的 Bearer Token，前端零接触\n   渲染函数均为纯模板（无副作用），数据获取由事件/初始化层触发 */\nfunction mzyWrite(auxId, method, path, bodyObj) {\n  if (RUNTIME.mode !== \"server\") return Promise.reject(new Error(\"管理操作需云端模式（部署 Worker 后由网关注入 Token）\"));\n  var body = bodyObj === null ? undefined : JSON.stringify(bodyObj);\n  var h = { \"Authorization\": \"Bearer \" + sessionToken() };\n  if (body) h[\"Content-Type\"] = \"application/json\";\n  return fetch(\"api/proxy/\" + auxId + (path || \"\"), { method: method, headers: h, body: body })\n    .then(function (r) { return r.json().then(function (j) { return { status: r.status, j: j }; }); })\n    .then(function (res) {\n      if (res.status >= 400 || !res.j || res.j.ok === false) throw new Error((res.j && res.j.error) || \"HTTP \" + res.status);\n      return res.j;\n    });\n}\n/* 辅助数据拉取（镜像/模组清单/工单完整列表）：数据层 → state → 统一刷新\n   与 fetchService 同语义：server 模式下真实 API 优先，demo 数据仅作未连接时兜底 */\nfunction mzyFetchAux(auxId, key, silent) {\n  if (RUNTIME.mode !== \"server\") return Promise.resolve();\n  return mzyWrite(auxId, \"GET\", \"\", null)\n    .then(function (j) { state.mzy[key] = j; if (!silent) refreshAll(); })\n    .catch(function (err) { if (!silent) showToast((key === \"mirrors\" ? \"镜像\" : key === \"modsList\" ? \"模组清单\" : \"工单列表\") + \"获取失败：\" + err.message, \"err\"); });\n}\nfunction mzyFetchAllAux(silent) {\n  mzyFetchAux(\"dl_mirrors\", \"mirrors\", silent);\n  mzyFetchAux(\"dl_mods\", \"modsList\", silent);\n  mzyFetchAux(\"tickets_list\", \"tlist\", true);\n}\n/* 纯模板：工单管理卡（选中 → 详情 → 回复 / AI 草稿 / 关闭 / 重开 / 删除） */\nfunction mzyTicketAdminHtml() {\n  var m = state.mzy;\n  var local = RUNTIME.mode !== \"server\";\n  var demo = state.config.demoMode;\n  var head = '<div class=\"card wiki-admin\"><div class=\"wa-head\">' + ic(\"tickets\", 16) + \"<b>工单管理</b>\" +\n    '<span class=\"grow\"></span><button class=\"btn small\" data-action=\"mzy-trefresh\">' + ic(\"refresh\", 14) + \"刷新列表</button></div>\" +\n    '<div class=\"note\">' + (local ? \"本地模式仅可查看公开数据，工单管理需部署 Worker（云端模式）后使用。\"\n      : \"回复将通过邮件通知玩家；「AI 草稿」基于 Wiki 知识库生成。\" + (demo ? \"若 API 尚未连上，下方列表为演示数据，请勿执行写操作。\" : \"\")) + \"</div>\";\n  if (local) return head + \"</div>\";\n  var list = (m.tlist && m.tlist.tickets) || (demo ? (state.demo.tickets && state.demo.tickets.recentTickets) || [] : []);\n  var opts = '<option value=\"\">— 选择要处理的工单 —</option>';\n  list.forEach(function (t) {\n    opts += '<option value=\"' + esc(t.id) + '\"' + (m.tsel === t.id ? \" selected\" : \"\") + \">\" +\n      esc(t.id + \" · \" + (t.nickname || \"?\") + \" · \" + statusText(t.status)) + \"</option>\";\n  });\n  var d = m.tdetail && m.tdetail.ticket;\n  var detail = \"\";\n  if (m.tloading) detail = '<div class=\"note\">正在加载工单详情…</div>';\n  else if (d) {\n    var replies = (d.replies || []).map(function (r) {\n      var mine = r.from === \"admin\";\n      return '<div class=\"wa-label\" style=\"margin-bottom:2px\">' + (mine ? \"管理员回复\" : \"玩家留言\") + \" · \" + esc(fmtTime(r.at)) + \"</div>\" +\n        '<div class=\"note\" style=\"white-space:pre-wrap\">' + esc(r.content) + \"</div>\";\n    }).join(\"\");\n    detail = '<div class=\"wa-grid\"><div><label class=\"wa-label\">玩家</label><div class=\"note\">' + esc(d.nickname || \"—\") + \"（游戏名：\" + esc(d.gamename || \"—\") + \"）</div></div>\" +\n      '<div><label class=\"wa-label\">邮箱 / 状态</label><div class=\"note\">' + esc(d.email || \"—\") + \" · \" +\n      '<span class=\"badge ' + badgeFor(d.status) + '\">' + esc(statusText(d.status)) + \"</span></div></div></div>\" +\n      '<label class=\"wa-label\">工单内容（' + esc(fmtTime(d.createdAt)) + \"）</label>\" +\n      '<div class=\"note\" style=\"white-space:pre-wrap\">' + esc(d.content || \"—\") + \"</div>\" +\n      (replies ? '<label class=\"wa-label\">往来回复</label>' + replies : \"\") +\n      '<label class=\"wa-label\">回复内容（发送后邮件通知玩家）</label>' +\n      '<textarea class=\"wa-input\" rows=\"5\" data-mfield=\"reply\" placeholder=\"填写回复内容…\">' + esc(m.reply || \"\") + \"</textarea>\" +\n      '<div class=\"wa-actions\">' +\n      '<button class=\"btn primary\" data-action=\"mzy-treply\">' + ic(\"out\", 14) + \"发送回复</button>\" +\n      '<button class=\"btn\" data-action=\"mzy-tai\">' + ic(\"wiki\", 14) + \"AI 草稿</button>\" +\n      (d.status === \"closed\" ? '<button class=\"btn\" data-action=\"mzy-treopen\">重新打开</button>' : '<button class=\"btn\" data-action=\"mzy-tclose\">关闭工单</button>') +\n      '<button class=\"btn danger\" data-action=\"mzy-tdel\">删除工单</button>' +\n      \"</div>\";\n  }\n  return head +\n    '<label class=\"wa-label\">选择工单（' + list.length + \" 条）</label>\" +\n    '<select class=\"wa-input\" data-mfield=\"tsel\">' + opts + \"</select>\" + detail + \"</div>\";\n}\n/* 纯模板：一键发布 + 模组清单 */\nfunction mzyModsAdminHtml() {\n  var m = state.mzy;\n  var local = RUNTIME.mode !== \"server\";\n  var demo = state.config.demoMode;\n  var head = '<div class=\"card wiki-admin\"><div class=\"wa-head\">' + ic(\"mods\", 16) + \"<b>模组包发布</b>\" +\n    '<span class=\"grow\"></span><button class=\"btn small\" data-action=\"mzy-mrefresh\">' + ic(\"refresh\", 14) + \"刷新清单</button></div>\" +\n    '<div class=\"note\">' + (local ? \"本地模式仅可查看公开清单，发布需部署 Worker（云端模式）后使用。\"\n      : \"发布将打包当前全部模组、自动递增版本号并创建 GitHub Release（modpack.zip / 更新器）。\" + (demo ? \"清单未连上 API 时显示为演示数据。\" : \"\")) + \"</div>\";\n  var pub = \"\";\n  if (!local) {\n    pub = '<label class=\"wa-label\">发布说明（可选，≤500 字）</label>' +\n      '<textarea class=\"wa-input\" rows=\"3\" data-mfield=\"pubMsg\" placeholder=\"本次更新内容…\">' + esc(m.pubMsg || \"\") + \"</textarea>\" +\n      '<div class=\"wa-actions\"><button class=\"btn primary\" data-action=\"mzy-publish\">' + ic(\"export\", 14) + \"打包发布新版本</button></div>\";\n  }\n  var mods = (m.modsList && m.modsList.mods) || (state.demo.mods && state.demo.mods.modsList) || [];\n  var rows = mods.slice(0, 12).map(function (x) {\n    return \"<tr><td>\" + esc(x.name) + '</td><td class=\"num\">' + esc(fmtBytes(x.size)) + \"</td></tr>\";\n  }).join(\"\");\n  var tbl = mods.length ? '<label class=\"wa-label\">模组清单（共 ' + mods.length + \" 个，显示前 12）</label>\" +\n    '<div class=\"tbl-wrap\"><table><thead><tr><th>文件名</th><th>大小</th></tr></thead><tbody>' + rows + \"</tbody></table>\" +\n    (mods.length > 12 ? '<div class=\"note\">仅显示前 12 个模组</div>' : \"\") + \"</div>\" : \"\";\n  return head + pub + tbl + \"</div>\";\n}\n/* 纯模板：下载信息卡（镜像多线路 + 一键复制） */\nfunction mzyDlInfoHtml(svc) {\n  var m = state.mzy;\n  var local = RUNTIME.mode !== \"server\";\n  var mirrors = (m.mirrors && m.mirrors.mirrors) || (local ? [] : (state.demo.downloads && state.demo.downloads.mirrors) || []);\n  var head = '<div class=\"card wiki-admin\"><div class=\"wa-head\">' + ic(\"out\", 16) + \"<b>镜像加速下载</b>\" +\n    '<span class=\"grow\"></span><button class=\"btn small\" data-action=\"mzy-drefresh\">' + ic(\"refresh\", 14) + \"刷新镜像</button></div>\" +\n    '<div class=\"note\">' + (local ? \"本地模式：镜像列表由服务端网关获取，云端模式可用。\" : \"点击「复制」获取镜像直链；GitHub 源站在国内可能较慢，推荐使用镜像。\") + \"</div>\";\n  if (!mirrors.length) return head + \"</div>\";\n  var rows = mirrors.map(function (x, i) {\n    return '<div class=\"wa-actions\" style=\"margin:0 0 6px;padding:0\">' +\n      '<span class=\"badge b-blue\" style=\"align-self:center\">' + esc(x.name) + \"</span>\" +\n      '<span class=\"note grow\" style=\"overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">' + esc(x.url) + \"</span>\" +\n      '<button class=\"btn small\" data-action=\"mzy-copy\" data-url=\"' + esc(x.url) + '\">复制</button></div>';\n  }).join(\"\");\n  return head + rows + \"</div>\";\n}\n/* 纯模板：错误报告查询卡（report_id + poll token → 分析结果） */\nfunction mzyErQueryHtml() {\n  var m = state.mzy;\n  var local = RUNTIME.mode !== \"server\";\n  var head = '<div class=\"card wiki-admin\"><div class=\"wa-head\">' + ic(\"errors\", 16) + \"<b>分析报告查询</b></div>\" +\n    '<div class=\"note\">' + (local ? \"查询经服务端网关转发，需云端模式。\"\n      : \"上传接口的响应含 report_id 与 poll.token（或玩家向你提供），粘贴后查询 AI 分析进度与结果。报告完成后也会自动生成工单并邮件发送。\") + \"</div>\";\n  if (local) return head + \"</div>\";\n  var r = m.erResult;\n  var result = \"\";\n  if (m.erLoading) result = '<div class=\"note\">正在查询…</div>';\n  else if (m.erError) result = '<div class=\"note\" style=\"color:var(--red-t)\">查询失败：' + esc(m.erError) + \"</div>\";\n  else if (r && r.report_id) {\n    result = '<label class=\"wa-label\">报告 ' + esc(r.report_id) + ' · <span class=\"badge ' + badgeFor(r.status) + '\">' + esc(statusText(r.status)) + \"</span>\" +\n      (r.ticket_id ? \" · 已生成工单 \" + esc(r.ticket_id) : \"\") + \"</label>\" +\n      (r.result ? '<div class=\"note\" style=\"white-space:pre-wrap;max-height:420px;overflow-y:auto\">' + esc(r.result) + \"</div>\" : '<div class=\"note\">暂无分析结果，请稍后刷新重试。</div>');\n  }\n  return head +\n    '<div class=\"wa-grid\"><div><label class=\"wa-label\">报告 ID</label><input class=\"wa-input\" data-mfield=\"erId\" placeholder=\"如 ERMTNLXZQ4BAEA165D\" value=\"' + esc(m.erId || \"\") + '\"></div>' +\n    '<div><label class=\"wa-label\">poll.token</label><input class=\"wa-input\" data-mfield=\"erTok\" placeholder=\"上传响应中的 token\" value=\"' + esc(m.erTok || \"\") + '\"></div></div>' +\n    '<div class=\"wa-actions\"><button class=\"btn primary\" data-action=\"mzy-erquery\">' + ic(\"refresh\", 14) + \"查询分析结果</button></div>\" + result + \"</div>\";\n}\n\n/* 事件层：工单处理（选中/回复/AI/关闭/重开/删除），操作后同步详情与列表 */\nfunction mzyTicketOpen(id) {\n  var m = state.mzy;\n  m.tsel = id || \"\"; m.tdetail = null; m.reply = \"\";\n  if (!id) { refreshAll(); return; }\n  m.tloading = true; refreshAll();\n  mzyWrite(\"tickets_list\", \"GET\", \"/\" + encodeURIComponent(id), null)\n    .then(function (j) { m.tdetail = j; m.tloading = false; refreshAll(); })\n    .catch(function (err) { m.tloading = false; showToast(\"工单详情获取失败：\" + err.message, \"err\"); refreshAll(); });\n}\nfunction mzyTicketRefresh() {\n  state.mzy.tsel = \"\"; state.mzy.tdetail = null; state.mzy.reply = \"\";\n  mzyFetchAux(\"tickets_list\", \"tlist\");\n}\nfunction mzyTicketReply() {\n  var m = state.mzy, id = m.tsel;\n  var text = String(m.reply || \"\").trim();\n  if (!id || !m.tdetail) { showToast(\"请先选择工单\", \"err\"); return; }\n  if (!text) { showToast(\"回复内容不能为空\", \"err\"); return; }\n  confirmDialog(\"回复工单\", \"将回复 \" + id + \" 并邮件通知玩家。确定发送？\", function () {\n    showToast(\"正在发送…\");\n    mzyWrite(\"tickets_list\", \"POST\", \"/\" + encodeURIComponent(id) + \"/reply\", { content: text })\n      .then(function () { m.reply = \"\"; showToast(\"已回复并通知玩家\", \"good\"); return mzyWrite(\"tickets_list\", \"GET\", \"/\" + encodeURIComponent(id), null); })\n      .then(function (j) { m.tdetail = j; refreshAll(); mzyFetchAux(\"tickets_list\", \"tlist\", true); })\n      .catch(function (err) { showToast(\"回复失败：\" + err.message, \"err\"); });\n  });\n}\nfunction mzyTicketAI() {\n  var m = state.mzy, id = m.tsel;\n  if (!id || !m.tdetail) { showToast(\"请先选择工单\", \"err\"); return; }\n  showToast(\"正在基于知识库生成草稿…\");\n  mzyWrite(\"tickets_list\", \"POST\", \"/\" + encodeURIComponent(id) + \"/ai\", {})\n    .then(function (j) {\n      m.reply = (j.draft || \"\").trim();\n      if (!m.reply) throw new Error(\"AI 未返回草稿\");\n      showToast(\"草稿已填入，可修改后发送\", \"good\"); refreshAll();\n    })\n    .catch(function (err) { showToast(\"AI 草稿失败：\" + err.message, \"err\"); });\n}\nfunction mzyTicketSetStatus(reopen) {\n  var m = state.mzy, id = m.tsel;\n  if (!id || !m.tdetail) { showToast(\"请先选择工单\", \"err\"); return; }\n  confirmDialog(reopen ? \"重新打开工单\" : \"关闭工单\", \"将把 \" + id + (reopen ? \" 重新置为待处理\" : \" 置为已关闭\") + (reopen ? \"。\" : \"，并邮件通知玩家。\"), function () {\n    showToast(\"正在操作…\");\n    mzyWrite(\"tickets_list\", \"POST\", \"/\" + encodeURIComponent(id) + (reopen ? \"/reopen\" : \"/close\"), {})\n      .then(function () { showToast(reopen ? \"已重新打开\" : \"已关闭工单\", \"good\"); return mzyWrite(\"tickets_list\", \"GET\", \"/\" + encodeURIComponent(id), null); })\n      .then(function (j) { m.tdetail = j; refreshAll(); mzyFetchAux(\"tickets_list\", \"tlist\", true); })\n      .catch(function (err) { showToast(\"操作失败：\" + err.message, \"err\"); });\n  });\n}\nfunction mzyTicketDelete() {\n  var m = state.mzy, id = m.tsel;\n  if (!id) { showToast(\"请先选择工单\", \"err\"); return; }\n  confirmDialog(\"删除工单\", \"将永久删除 \" + id + \"，此操作不可撤销。确定删除？\", function () {\n    showToast(\"正在删除…\");\n    mzyWrite(\"tickets_list\", \"DELETE\", \"/\" + encodeURIComponent(id), null)\n      .then(function () { m.tsel = \"\"; m.tdetail = null; m.reply = \"\"; showToast(\"已删除工单\", \"good\"); refreshAll(); mzyFetchAux(\"tickets_list\", \"tlist\", true); })\n      .catch(function (err) { showToast(\"删除失败：\" + err.message, \"err\"); });\n  });\n}\n/* 事件层：一键发布新版本（自动打包 + bump 版本 + GitHub Release） */\nfunction mzyPublish() {\n  var m = state.mzy;\n  var msg = String(m.pubMsg || \"\").trim();\n  confirmDialog(\"打包发布新版本\", \"将打包当前全部模组、自动递增版本号并创建 GitHub Release\" + (msg ? \"（附发布说明）\" : \"\") + \"。确定发布？\", function () {\n    showToast(\"正在打包发布，视模组数量可能需要 1-2 分钟…\");\n    mzyWrite(\"mods_pub\", \"POST\", \"\", msg ? { message: msg } : {})\n      .then(function (j) {\n        m.pubMsg = \"\";\n        showToast(\"发布成功\" + (j.release && j.release.tag ? \"：\" + j.release.tag : \"\"), \"good\");\n        fetchService(\"mods\", true);\n        mzyFetchAux(\"dl_mods\", \"modsList\", true);\n      })\n      .catch(function (err) { showToast(\"发布失败：\" + err.message, \"err\"); });\n  });\n}\n/* 事件层：错误报告分析结果查询 */\nfunction mzyErQuery() {\n  var m = state.mzy;\n  var id = String(m.erId || \"\").trim(), tok = String(m.erTok || \"\").trim();\n  if (!id || !tok) { showToast(\"报告 ID 与 poll.token 均必填\", \"err\"); return; }\n  if (RUNTIME.mode !== \"server\") { showToast(\"查询需云端模式（网关转发）\", \"err\"); return; }\n  m.erResult = null; m.erError = \"\"; m.erLoading = true; refreshAll();\n  mzyWrite(\"er_q\", \"GET\", \"/\" + encodeURIComponent(id) + \"?token=\" + encodeURIComponent(tok), null)\n    .then(function (j) { m.erResult = j; m.erLoading = false; refreshAll(); })\n    .catch(function (err) { m.erError = err.message; m.erLoading = false; refreshAll(); });\n}\nfunction mzyCopy(url) {\n  var done = function () { showToast(\"已复制镜像链接\", \"good\"); };\n  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done, function () { showToast(\"复制失败\", \"err\"); });\n  else showToast(\"浏览器不支持一键复制，请长按链接手动复制\", \"err\");\n}\n/* 表单防丢值：管理卡输入实时同步到 state（与 wikiSyncForm 同模式） */\nfunction mzySyncForm(e) {\n  var el = e.target.closest ? e.target.closest(\"[data-mfield]\") : null;\n  if (!el) return;\n  state.mzy[el.getAttribute(\"data-mfield\")] = el.value;\n}\n\n/* 统一刷新入口：只调渲染函数，渲染函数之间禁止互调 */\nfunction refreshAll() {\n  renderBrand();\n  renderNav();\n  renderHeaderStatus();\n  renderBanner();\n  renderToday();\n  renderOverview();\n  renderService();\n}\n\n/* ---------- 设置面板 ---------- */\nfunction fillSettings() {\n  $(\"cfgBrand\").value = state.config.brand || \"\";\n  $(\"cfgDemo\").checked = !!state.config.demoMode;\n  $(\"cfgPoll\").value = String(state.config.pollMinutes || 0);\n  var rb = $(\"runtimeBadge\");\n  if (RUNTIME.mode === \"server\") {\n    rb.className = \"runtime-badge server\";\n    rb.innerHTML = '<span class=\"rdot\"></span>云端后端模式（CF Worker + D1）· 数据自动同步 · API 网关集中调用';\n  } else {\n    rb.className = \"runtime-badge\";\n    rb.innerHTML = '<span class=\"rdot\"></span>本地模式 · 数据存本机浏览器（部署到 Cloudflare Worker 可启用 D1 云端）';\n  }\n  /* 云同步区块 */\n  var sEnv = syncEnv();\n  $(\"syncRepoName\").textContent = sEnv.REPO || \"(未配置仓库)\";\n  $(\"syncTarget\").textContent = sEnv.REPO ? sEnv.REPO + \" @ \" + sEnv.BRANCH + \" : \" + sEnv.PATH : \"未配置（在页面文件 WB_ENV.SYNC 中设置）\";\n  $(\"syncToken\").value = syncToken();\n  $(\"syncAuto\").checked = syncAutoOn();\n  $(\"syncTokens\").checked = syncTokensOn();\n  var last = null;\n  try { last = localStorage.getItem(LS_LAST_SYNC); } catch (e) {}\n  $(\"syncStatus\").textContent = syncToken() ? (last || \"就绪，可手动上传/恢复\") : \"未填写 Token，云同步未启用\";\n  var html = \"\";\n  SVC_DEFS.forEach(function (def) {\n    var svc = null;\n    state.config.services.forEach(function (s) { if (s.id === def.id) svc = s; });\n    if (!svc) return;\n    var st = computeStatus(svc);\n    html += '<details class=\"svc-block svc-c-' + def.id + '\" data-svc=\"' + def.id + '\">' +\n      \"<summary><span class=\\\"s-ico\\\">\" + ic(def.icon, 15) + \"</span>\" + esc(svc.name) + '<span class=\"tag badge ' + badgeFor(STATUS_TEXT[st]) + '\">' + STATUS_TEXT[st] + \"</span></summary>\" +\n      '<div class=\"svc-form\">' +\n      '<label class=\"chk\"><input type=\"checkbox\" class=\"f-enabled\"' + (svc.enabled ? \" checked\" : \"\") + \"> 启用该服务</label>\" +\n      '<div class=\"grid2\">' +\n      '<div class=\"form-row\"><label>显示名称</label><input type=\"text\" class=\"f-name\" value=\"' + esc(svc.name) + '\"></div>' +\n      '<div class=\"form-row\"><label>服务地址（前端，用于跳转）</label><input type=\"text\" class=\"f-url\" value=\"' + esc(svc.url) + '\" placeholder=\"https://dl.example.com\"></div>' +\n      \"</div>\" +\n      '<div class=\"form-row\"><label>API 地址（返回 JSON）</label><input type=\"text\" class=\"f-api\" value=\"' + esc(svc.baseUrl) + '\" placeholder=\"https://dl.example.com/api/stats\"></div>' +\n      '<div class=\"grid3\">' +\n      '<div class=\"form-row\"><label>认证方式</label><select class=\"f-auth\">' +\n      '<option value=\"none\"' + (svc.authType === \"none\" ? \" selected\" : \"\") + \">无需认证</option>\" +\n      '<option value=\"bearer\"' + (svc.authType === \"bearer\" ? \" selected\" : \"\") + \">Bearer Token</option>\" +\n      '<option value=\"header\"' + (svc.authType === \"header\" ? \" selected\" : \"\") + \">自定义 Header</option>\" +\n      \"</select></div>\" +\n      '<div class=\"form-row\"><label>Token / Key</label><input type=\"text\" class=\"f-token\" value=\"' + esc(svc.token) + '\" placeholder=\"留空则不发送\"></div>' +\n      '<div class=\"form-row\"><label>Header 名（自定义时）</label><input type=\"text\" class=\"f-header\" value=\"' + esc(svc.headerName) + '\" placeholder=\"X-API-Key\"></div>' +\n      \"</div>\" +\n      '<div class=\"form-row\"><label>数据映射 JSON（metrics 指标 / list 列表 / todo 待处理提取）</label>' +\n      '<textarea class=\"f-mapping\" rows=\"12\" spellcheck=\"false\">' + esc(JSON.stringify(normalizeAdvanced(svc.id, svc.advanced), null, 2)) + \"</textarea></div>\" +\n      '<div class=\"btn-row\">' +\n      '<button class=\"btn small\" data-action=\"test-conn\" data-svc=\"' + def.id + '\">' + ic(\"refresh\", 14) + \"测试连接</button>\" +\n      '<button class=\"btn small ghost\" data-action=\"reset-mapping\" data-svc=\"' + def.id + '\">恢复默认映射</button>' +\n      \"</div>\" +\n      '<pre class=\"test-result hidden\"></pre>' +\n      \"</div></details>\";\n  });\n  $(\"svcForms\").innerHTML = html;\n}\nfunction collectSvcFromForm(block, defId) {\n  var svc = null;\n  state.config.services.forEach(function (s) { if (s.id === defId) svc = s; });\n  if (!svc) return null;\n  var next = Object.assign({}, svc);\n  next.enabled = block.querySelector(\".f-enabled\").checked;\n  next.name = block.querySelector(\".f-name\").value.trim() || svc.name;\n  next.url = block.querySelector(\".f-url\").value.trim();\n  next.baseUrl = block.querySelector(\".f-api\").value.trim();\n  var formAuth = block.querySelector(\".f-auth\").value;\n  var formTok = block.querySelector(\".f-token\").value.trim();\n  /* 保护：云端模式下凭据由 D1 保管，表单里的认证/Token 是空的占位。\n     若用户未在表单填 Token，则保留原配置（避免把云端已配好的 Bearer 抹成 none → 401）。 */\n  if (!formTok && svc.token) { next.authType = svc.authType; next.token = svc.token; }\n  else { next.authType = formAuth; next.token = formTok; }\n  next.headerName = block.querySelector(\".f-header\").value.trim() || \"X-API-Key\";\n  var raw = block.querySelector(\".f-mapping\").value;\n  var parsed = JSON.parse(raw); // 交给调用方 try/catch\n  if (typeof parsed !== \"object\" || parsed === null || Array.isArray(parsed)) throw new Error(defId + \" 的映射必须是 JSON 对象\");\n  if (parsed.metrics && !Array.isArray(parsed.metrics)) throw new Error(defId + \" 的 metrics 必须是数组\");\n  /* 空映射/缺 list 结构不报错也不入库存脏值，静默回退页面内置默认 */\n  next.advanced = normalizeAdvanced(defId, parsed);\n  return next;\n}\nfunction saveSettingsFromForm() {\n  var brand = $(\"cfgBrand\").value.trim() || \"聚合工作台\";\n  var demoMode = $(\"cfgDemo\").checked;\n  var poll = Math.max(0, parseInt($(\"cfgPoll\").value, 10) || 0);\n  /* 云同步设置（Token/开关存本设备） */\n  try {\n    localStorage.setItem(LS_SYNC_TOKEN, $(\"syncToken\").value.trim());\n    localStorage.setItem(LS_SYNC_AUTO, $(\"syncAuto\").checked ? \"1\" : \"0\");\n    localStorage.setItem(LS_SYNC_TOKENS, $(\"syncTokens\").checked ? \"1\" : \"0\");\n  } catch (e) {}\n  var services = [];\n  var blocks = document.querySelectorAll(\"#svcForms .svc-block\");\n  for (var i = 0; i < blocks.length; i++) {\n    var block = blocks[i];\n    var sid = block.getAttribute(\"data-svc\");\n    var svc = collectSvcFromForm(block, sid);\n    if (!svc) continue;\n    services.push(svc);\n  }\n  if (services.length !== state.config.services.length) throw new Error(\"服务配置数量异常，请刷新页面重试\");\n  state.config.brand = brand;\n  state.config.demoMode = demoMode;\n  state.config.pollMinutes = poll;\n  state.config.services = services;\n  saveConfig();\n  setupPoll();\n}\n/* 用页面 WB_ENV 内置配置覆盖本设备设置 */\nfunction applyEnvConfig() {\n  var envCfg = buildConfigFromEnv();\n  state.config.brand = envCfg.brand;\n  state.config.demoMode = envCfg.demoMode;\n  state.config.pollMinutes = envCfg.pollMinutes;\n  state.config.services = state.config.services.map(function (svc, i) {\n    var e = envCfg.services[i];\n    if (!e) return svc;\n    return Object.assign({}, svc, {\n      name: e.name, url: e.url, baseUrl: e.baseUrl,\n      /* 认证方式与 Token 不由页面内置配置覆盖：\n         Worker 版凭据存于 D1（网关注入），页面 AUTH/TOKEN 恒为空，\n         若覆盖会把云端已配好的 Bearer 抹成 none，导致管理接口 401。\n         仅当页面内置配置确实带了非空 Token 时才覆盖（本地模式兼容）。 */\n      authType: (e.token ? e.authType : svc.authType),\n      token: (e.token || svc.token),\n      headerName: e.headerName\n    });\n  });\n  saveConfig();\n  setupPoll();\n  fillSettings();\n  refreshAll();\n  fetchAll();\n  showToast(\"已应用页面内置 API 配置（云端凭据保持不变）\", \"good\");\n}\n\nfunction testConnection(defId) {\n  var block = document.querySelector('#svcForms .svc-block[data-svc=\"' + defId + '\"]');\n  var pre = block.querySelector(\".test-result\");\n  pre.classList.remove(\"hidden\", \"good\", \"bad\");\n  var svc;\n  try { svc = collectSvcFromForm(block, defId); }\n  catch (e) {\n    pre.textContent = \"映射 JSON 有误：\" + e.message;\n    pre.classList.add(\"bad\");\n    return;\n  }\n  if (!svc.baseUrl) {\n    pre.textContent = \"请先填写 API 地址\";\n    pre.classList.add(\"bad\");\n    return;\n  }\n  pre.textContent = \"请求中…\" + svc.baseUrl;\n  if (RUNTIME.mode === \"server\") {\n    pre.textContent = \"请求中（经后端网关代理）…\";\n    fetch(\"api/proxy-test\", { method: \"POST\", headers: apiHeaders(), body: JSON.stringify({ service: { baseUrl: svc.baseUrl, authType: svc.authType, token: svc.token, headerName: svc.headerName } }) })\n      .then(function (r) { if (!r.ok) throw new Error(\"HTTP \" + r.status); return r.json(); })\n      .then(function (data) {\n        var top = (data && typeof data === \"object\") ? \"顶层字段：\" + Object.keys(data).join(\", \") + \"\\n\\n\" : \"\";\n        var body = JSON.stringify(data, null, 2);\n        pre.textContent = \"✓ 连接成功（经 D1 网关）\\n\" + top + body.slice(0, 1200) + (body.length > 1200 ? \"\\n…（已截断）\" : \"\");\n        pre.classList.add(\"good\");\n      })\n      .catch(function (err) {\n        pre.textContent = \"✗ 失败：\" + ((err && err.name === \"AbortError\") ? \"请求超时（10s）\" : (err && err.message) || \"未知错误\") +\n          \"\\n提示：保存设置后，后端会自动把该服务配置写入 D1，之后用 api/proxy/<服务> 即可集中调用。\";\n        pre.classList.add(\"bad\");\n      });\n    return;\n  }\n  callServiceApi(svc)\n    .then(function (data) {\n      var top = (data && typeof data === \"object\") ? \"顶层字段：\" + Object.keys(data).join(\", \") + \"\\n\\n\" : \"\";\n      var body = JSON.stringify(data, null, 2);\n      pre.textContent = \"✓ 连接成功\\n\" + top + body.slice(0, 1200) + (body.length > 1200 ? \"\\n…（已截断）\" : \"\");\n      pre.classList.add(\"good\");\n    })\n    .catch(function (err) {\n      pre.textContent = \"✗ 失败：\" + ((err && err.name === \"AbortError\") ? \"请求超时（10s）\" : (err && err.message) || \"未知错误\") +\n        \"\\n提示：若浏览器控制台出现 CORS 报错，需在 API 服务端开启跨域允许。\";\n      pre.classList.add(\"bad\");\n    });\n}\n\n/* ---------- 备份 / 恢复 / 清空 ---------- */\nfunction exportBackup() {\n  var payload = { version: 1, type: \"wb-hub-backup\", exportedAt: new Date().toISOString(), config: state.config, todos: state.todos };\n  var blob = new Blob([JSON.stringify(payload, null, 2)], { type: \"application/json\" });\n  var a = document.createElement(\"a\");\n  var d = new Date();\n  var p = function (n) { return n < 10 ? \"0\" + n : \"\" + n; };\n  a.href = URL.createObjectURL(blob);\n  a.download = (state.config.brand || \"聚合工作台\") + \"备份-\" + d.getFullYear() + p(d.getMonth() + 1) + p(d.getDate()) + \".json\";\n  document.body.appendChild(a);\n  a.click();\n  setTimeout(function () { URL.revokeObjectURL(a.href); a.remove(); }, 300);\n  showToast(\"备份已导出\", \"good\");\n}\nfunction importBackup(file) {\n  var reader = new FileReader();\n  reader.onload = function () {\n    try {\n      var data = JSON.parse(reader.result);\n      if (!data || (!data.config && !data.todos)) throw new Error(\"不是有效的工作台备份文件\");\n      if (data.config) state.config = mergeConfig(data.config);\n      if (Array.isArray(data.todos)) state.todos = data.todos;\n      saveConfig(); saveTodos();\n      fillSettings();\n      setupPoll();\n      refreshAll();\n      fetchAll();\n      showToast(\"导入成功，配置已恢复\", \"good\");\n    } catch (e) {\n      showToast(\"导入失败：\" + e.message, \"err\");\n    }\n  };\n  reader.onerror = function () { showToast(\"读取文件失败\", \"err\"); };\n  reader.readAsText(file);\n}\nfunction confirmDialog(title, text, onYes, onNo) {\n  $(\"confirmTitle\").textContent = title;\n  $(\"confirmText\").textContent = text;\n  $(\"confirmModal\").classList.remove(\"hidden\");\n  $(\"confirmYes\").onclick = function () { $(\"confirmModal\").classList.add(\"hidden\"); onYes(); };\n  $(\"confirmNo\").onclick = function () { $(\"confirmModal\").classList.add(\"hidden\"); if (onNo) onNo(); };\n}\n\n/* ---------- toast ---------- */\nvar toastTimer = null;\nfunction showToast(msg, type) {\n  var t = $(\"toast\");\n  t.textContent = msg;\n  t.className = type === \"err\" ? \"err\" : type === \"good\" ? \"good\" : \"\";\n  t.classList.add(\"show\");\n  if (toastTimer) clearTimeout(toastTimer);\n  toastTimer = setTimeout(function () { t.classList.remove(\"show\"); }, 2600);\n}\n\n/* ---------- 事件处理（改数据 → refreshAll，禁止渲染函数互相触发） ---------- */\nfunction gotoView(view) {\n  state.view = view;\n  refreshAll();\n  try { window.scrollTo({ top: 0, behavior: \"smooth\" }); } catch (e) { window.scrollTo(0, 0); }\n}\nfunction bindEvents() {\n  $(\"btnRefresh\").innerHTML = ic(\"refresh\");\n  $(\"btnExportTop\").innerHTML = ic(\"export\");\n  $(\"btnSettings\").innerHTML = ic(\"gear\");\n  $(\"btnCloseSettings\").innerHTML = ic(\"x\");\n  $(\"clockIcon\").innerHTML = ic(\"clock\");\n  $(\"todayFoldBtn\").innerHTML = ic(\"chevron\");\n  $(\"brandIcon\").innerHTML = ic(\"hub\", 17);\n  applyTheme();\n\n  $(\"loginForm\").addEventListener(\"submit\", function (e) {\n    e.preventDefault();\n    attemptLogin();\n  });\n  $(\"btnApplyEnv\").addEventListener(\"click\", applyEnvConfig);\n  $(\"btnSyncUp\").addEventListener(\"click\", function () {\n    try { localStorage.setItem(LS_SYNC_TOKEN, $(\"syncToken\").value.trim()); } catch (e) {}\n    pushRemote(false);\n  });\n  $(\"btnSyncDown\").addEventListener(\"click\", function () {\n    try { localStorage.setItem(LS_SYNC_TOKEN, $(\"syncToken\").value.trim()); } catch (e) {}\n    pullRemote({ silent: false });\n  });\n  $(\"syncToken\").addEventListener(\"change\", function () {\n    try { localStorage.setItem(LS_SYNC_TOKEN, this.value.trim()); } catch (e) {}\n  });\n\n  $(\"mainNav\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action='goto']\");\n    if (el) gotoView(el.getAttribute(\"data-view\"));\n  });\n  $(\"main\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action]\");\n    if (!el) return;\n    var act = el.getAttribute(\"data-action\");\n    if (act === \"goto\") { gotoView(el.getAttribute(\"data-view\")); return; }\n    if (act === \"done-todo\") {\n      var id = el.getAttribute(\"data-id\");\n      state.todos.forEach(function (t) { if (t.id === id) t.done = true; });\n      saveTodos(); refreshAll(); showToast(\"已完成\");\n      return;\n    }\n    if (act === \"del-todo\") {\n      var did = el.getAttribute(\"data-id\");\n      state.todos = state.todos.filter(function (t) { return t.id !== did; });\n      saveTodos(); refreshAll();\n      return;\n    }\n    if (act === \"svc-refresh\") {\n      var sid = el.getAttribute(\"data-svc\");\n      if (sid) {\n        fetchService(sid);\n        /* 梦之韵：刷新服务时同步刷新对应辅助数据 */\n        if (sid === \"downloads\") mzyFetchAux(\"dl_mirrors\", \"mirrors\");\n        if (sid === \"mods\") mzyFetchAux(\"dl_mods\", \"modsList\");\n        if (sid === \"tickets\") mzyFetchAux(\"tickets_list\", \"tlist\");\n      } else { fetchAll(); mzyFetchAllAux(); }\n      return;\n    }\n    if (act === \"wiki-new\" || act === \"wiki-cancel\") {\n      state.wiki = { mode: \"new\", link: \"\", form: wikiFormDefault() };\n      refreshAll();\n      return;\n    }\n    if (act === \"wiki-submit\") { wikiSubmit(); return; }\n    if (act === \"wiki-del\") { wikiDelete(); return; }\n    /* 梦之韵管理操作 */\n    if (act === \"mzy-trefresh\") { mzyTicketRefresh(); return; }\n    if (act === \"mzy-treply\") { mzyTicketReply(); return; }\n    if (act === \"mzy-tai\") { mzyTicketAI(); return; }\n    if (act === \"mzy-tclose\") { mzyTicketSetStatus(false); return; }\n    if (act === \"mzy-treopen\") { mzyTicketSetStatus(true); return; }\n    if (act === \"mzy-tdel\") { mzyTicketDelete(); return; }\n    if (act === \"mzy-publish\") { mzyPublish(); return; }\n    if (act === \"mzy-erquery\") { mzyErQuery(); return; }\n    if (act === \"mzy-copy\") { mzyCopy(el.getAttribute(\"data-url\") || \"\"); return; }\n    if (act === \"mzy-drefresh\") { mzyFetchAux(\"dl_mirrors\", \"mirrors\"); return; }\n    if (act === \"mzy-mrefresh\") { mzyFetchAux(\"dl_mods\", \"modsList\"); return; }\n    if (act === \"open-settings\") {\n      state.config.bannerClosed = true; saveConfig();\n      fillSettings();\n      $(\"settingsOverlay\").classList.remove(\"hidden\");\n      return;\n    }\n  });\n  /* Wiki 内容管理表单：输入实时同步到 state，防止渲染刷新丢值 */\n  $(\"main\").addEventListener(\"input\", wikiSyncForm);\n  $(\"main\").addEventListener(\"change\", wikiSyncForm);\n  /* 梦之韵管理卡：下拉选择工单 / 表单实时同步 */\n  $(\"main\").addEventListener(\"change\", function (e) {\n    var el = e.target.closest ? e.target.closest(\"[data-mfield='tsel']\") : null;\n    if (el) { mzyTicketOpen(el.value); return; }\n    mzySyncForm(e);\n  });\n  $(\"main\").addEventListener(\"input\", mzySyncForm);\n  $(\"btnTheme\").addEventListener(\"click\", cycleTheme);\n  $(\"btnRefresh\").addEventListener(\"click\", function () {\n    var jobs = state.config.services.filter(function (s) { return s.enabled && s.baseUrl; }).length;\n    if (jobs) { fetchAll(); showToast(\"正在刷新 \" + jobs + \" 个服务…\"); }\n    else { refreshAll(); showToast(\"已刷新（当前为演示数据）\"); }\n  });\n  $(\"btnExportTop\").addEventListener(\"click\", exportBackup);\n  $(\"btnSettings\").addEventListener(\"click\", function () {\n    fillSettings();\n    $(\"settingsOverlay\").classList.remove(\"hidden\");\n  });\n\n  $(\"todaySection\").addEventListener(\"submit\", function (e) {\n    e.preventDefault();\n    var input = $(\"todoInput\");\n    var text = input.value.trim();\n    if (!text) { showToast(\"先输入待办内容\"); return; }\n    state.todos.unshift({ id: uid(), text: text, createdAt: Date.now(), done: false });\n    input.value = \"\";\n    saveTodos(); refreshAll();\n  });\n  $(\"todayFoldBtn\").addEventListener(\"click\", function () {\n    state.todayOpen = !state.todayOpen;\n    refreshAll();\n  });\n\n  $(\"demoBanner\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action]\");\n    if (!el) return;\n    if (el.getAttribute(\"data-action\") === \"open-settings\") {\n      state.config.bannerClosed = true; saveConfig();\n      fillSettings();\n      $(\"settingsOverlay\").classList.remove(\"hidden\");\n      return;\n    }\n    if (el.getAttribute(\"data-action\") === \"close-banner\") {\n      state.config.bannerClosed = true; saveConfig(); refreshAll();\n    }\n  });\n\n  $(\"settingsOverlay\").addEventListener(\"click\", function (e) {\n    var el = e.target.closest(\"[data-action]\");\n    if (el) {\n      var act = el.getAttribute(\"data-action\");\n      if (act === \"close-settings\") { $(\"settingsOverlay\").classList.add(\"hidden\"); return; }\n      if (act === \"test-conn\") { testConnection(el.getAttribute(\"data-svc\")); return; }\n      if (act === \"reset-mapping\") {\n        var sid = el.getAttribute(\"data-svc\");\n        var block = document.querySelector('#svcForms .svc-block[data-svc=\"' + sid + '\"]');\n        block.querySelector(\".f-mapping\").value = JSON.stringify(DEFAULT_MAPPING[sid], null, 2);\n        showToast(\"已恢复该服务默认映射\");\n        return;\n      }\n    }\n    if (e.target === $(\"settingsOverlay\")) $(\"settingsOverlay\").classList.add(\"hidden\");\n  });\n  $(\"btnSaveSettings\").addEventListener(\"click\", function () {\n    try {\n      saveSettingsFromForm();\n      $(\"settingsOverlay\").classList.add(\"hidden\");\n      refreshAll();\n      fetchAll();\n      showToast(\"设置已保存\", \"good\");\n    } catch (e) {\n      showToast(\"保存失败：\" + e.message, \"err\");\n    }\n  });\n  $(\"btnExport\").addEventListener(\"click\", exportBackup);\n  $(\"btnImport\").addEventListener(\"click\", function () { $(\"importFile\").click(); });\n  $(\"importFile\").addEventListener(\"change\", function () {\n    if (this.files && this.files[0]) importBackup(this.files[0]);\n    this.value = \"\";\n  });\n  $(\"btnWipe\").addEventListener(\"click\", function () {\n    confirmDialog(\"清空全部数据\", \"将删除所有 API 配置、待办与本地数据，且不可恢复。建议先「导出 JSON 备份」。确定继续吗？\", function () {\n      try { localStorage.removeItem(LS_CFG); localStorage.removeItem(LS_TODOS); } catch (e) {}\n      location.reload();\n    });\n  });\n}\n\n/* ---------- 登录门禁 ---------- */\nvar RUNTIME = { mode: \"local\" };      // local=纯本地 | server=云端后端(CF Worker + D1)\nvar SESSION_KEY = \"wb_hub_session\";   // 后端模式会话 Token（服务端 7 天有效）\nfunction sessionToken() {\n  try { return localStorage.getItem(SESSION_KEY) || \"\"; } catch (e) { return \"\"; }\n}\nfunction apiHeaders(extra) {\n  var h = { \"Content-Type\": \"application/json\" };\n  var t = sessionToken();\n  if (t) h[\"Authorization\"] = \"Bearer \" + t;\n  if (extra) { for (var k in extra) h[k] = extra[k]; }\n  return h;\n}\nfunction apiFetch(path, opts) {\n  opts = opts || {};\n  opts.headers = apiHeaders(opts.headers);\n  return fetch(path, opts).then(function (res) {\n    if (res.status === 401) {\n      try { localStorage.removeItem(SESSION_KEY); } catch (e) {}\n      showLogin(\"会话已过期，请重新登录\");\n      throw new Error(\"unauthorized\");\n    }\n    return res;\n  });\n}\nfunction detectMode() {\n  return fetch(\"api/health\", { headers: { \"Accept\": \"application/json\" } })\n    .then(function (r) { return r.ok ? r.json() : null; })\n    .then(function (j) { return (j && j.mode === \"server\") ? \"server\" : \"local\"; })\n    .catch(function () { return \"local\"; });\n}\nfunction isAuthed() {\n  try {\n    var until = Number(localStorage.getItem(LS_AUTH)) || 0;\n    return sessionStorage.getItem(\"wb_hub_auth\") === \"1\" || until > Date.now();\n  } catch (e) { return false; }\n}\nfunction loginFailState() {\n  try { return JSON.parse(localStorage.getItem(LS_FAIL)) || { n: 0, until: 0 }; }\n  catch (e) { return { n: 0, until: 0 }; }\n}\nfunction showLoginError(msg) {\n  var box = $(\"loginError\");\n  box.textContent = msg;\n  box.classList.remove(\"hidden\");\n}\nfunction updateLockUi() {\n  var st = loginFailState();\n  var btn = $(\"loginBtn\");\n  var remain = st.until - Date.now();\n  if (remain > 0) {\n    btn.disabled = true;\n    btn.textContent = \"已锁定 \" + Math.ceil(remain / 1000) + \" 秒\";\n    setTimeout(updateLockUi, 500);\n  } else {\n    btn.disabled = false;\n    btn.textContent = \"登录\";\n    if (st.n >= 5) { try { localStorage.removeItem(LS_FAIL); } catch (e) {} }\n  }\n}\nfunction attemptLogin() {\n  var user = $(\"loginUser\").value.trim();\n  var pass = $(\"loginPass\").value;\n  var env = (window.WB_ENV && window.WB_ENV.LOGIN) || {};\n  var st = loginFailState();\n  if (st.until - Date.now() > 0) { showLoginError(\"尝试次数过多，请稍后再试\"); updateLockUi(); return; }\n  if (user === (env.USER || \"admin\") && pass && passHash(pass) === (env.PASS_SHA256 || \"\")) {\n    try { localStorage.removeItem(LS_FAIL); } catch (e) {}\n    sessionStorage.setItem(\"wb_hub_auth\", \"1\");\n    if ($(\"loginRemember\").checked) {\n      try { localStorage.setItem(LS_AUTH, String(Date.now() + 7 * 86400e3)); } catch (e) {}\n    }\n    $(\"loginGate\").classList.add(\"hidden\");\n    $(\"loginPass\").value = \"\";\n    enterApp();\n  } else {\n    st.n = (st.n || 0) + 1;\n    if (st.n >= 5) { st.until = Date.now() + 30 * 1000; }\n    try { localStorage.setItem(LS_FAIL, JSON.stringify(st)); } catch (e) {}\n    showLoginError(\"账号或密码错误\" + (st.n >= 5 ? \"，已临时锁定 30 秒\" : \"（已失败 \" + st.n + \" 次）\"));\n    if (st.n >= 5) updateLockUi();\n  }\n}\nfunction showLogin(msg) {\n  $(\"loginGate\").classList.remove(\"hidden\");\n  $(\"loginTitle\").textContent = (window.WB_ENV && window.WB_ENV.BRAND) || \"聚合工作台\";\n  var tip = $(\"runtimeTip\");\n  if (tip) tip.textContent = RUNTIME.mode === \"server\" ? \"云端后端模式 · 配置与待办存 D1 数据库\" : \"本地模式 · 数据存本机浏览器\";\n  if (msg) showLoginError(msg); else $(\"loginError\").classList.add(\"hidden\");\n}\nfunction attemptLogin() {\n  var user = $(\"loginUser\").value.trim();\n  var pass = $(\"loginPass\").value;\n  var btn = $(\"loginBtn\");\n  if (RUNTIME.mode === \"server\") {\n    var st = loginFailState();\n    if (st.until - Date.now() > 0) { showLoginError(\"尝试次数过多，请稍后再试\"); updateLockUi(); return; }\n    btn.disabled = true; btn.textContent = \"登录中…\";\n    fetch(\"api/auth/login\", { method: \"POST\", headers: { \"Content-Type\": \"application/json\" }, body: JSON.stringify({ user: user, pass: pass }) })\n      .then(function (r) {\n        if (r.status === 401) throw new Error(\"账号或密码错误\");\n        if (!r.ok) throw new Error(\"HTTP \" + r.status);\n        return r.json();\n      })\n      .then(function (j) {\n        try { localStorage.removeItem(LS_FAIL); } catch (e) {}\n        try { localStorage.setItem(SESSION_KEY, j.token); } catch (e) {}\n        $(\"loginGate\").classList.add(\"hidden\");\n        $(\"loginPass\").value = \"\";\n        enterApp();\n      })\n      .catch(function (err) {\n        st.n = (st.n || 0) + 1;\n        if (st.n >= 5) { st.until = Date.now() + 30 * 1000; }\n        try { localStorage.setItem(LS_FAIL, JSON.stringify(st)); } catch (e) {}\n        showLoginError((err.message || \"登录失败\") + (st.n >= 5 ? \"，已临时锁定 30 秒\" : \"（已失败 \" + st.n + \" 次）\"));\n        if (st.n >= 5) updateLockUi();\n      })\n      .finally(function () { btn.disabled = false; btn.textContent = \"登录\"; });\n    return;\n  }\n  var env = (window.WB_ENV && window.WB_ENV.LOGIN) || {};\n  var st2 = loginFailState();\n  if (st2.until - Date.now() > 0) { showLoginError(\"尝试次数过多，请稍后再试\"); updateLockUi(); return; }\n  if (user === (env.USER || \"admin\") && pass && passHash(pass) === (env.PASS_SHA256 || \"\")) {\n    try { localStorage.removeItem(LS_FAIL); } catch (e) {}\n    sessionStorage.setItem(\"wb_hub_auth\", \"1\");\n    if ($(\"loginRemember\").checked) {\n      try { localStorage.setItem(LS_AUTH, String(Date.now() + 7 * 86400e3)); } catch (e) {}\n    }\n    $(\"loginGate\").classList.add(\"hidden\");\n    $(\"loginPass\").value = \"\";\n    enterApp();\n  } else {\n    st2.n = (st2.n || 0) + 1;\n    if (st2.n >= 5) { st2.until = Date.now() + 30 * 1000; }\n    try { localStorage.setItem(LS_FAIL, JSON.stringify(st2)); } catch (e) {}\n    showLoginError(\"账号或密码错误\" + (st2.n >= 5 ? \"，已临时锁定 30 秒\" : \"（已失败 \" + st2.n + \" 次）\"));\n    if (st2.n >= 5) updateLockUi();\n  }\n}\nfunction boot() {\n  $(\"loginLogo\").innerHTML = ic(\"hub\", 26);\n  bindEvents();\n  applyTheme();\n  detectMode().then(function (mode) {\n    RUNTIME.mode = mode;\n    document.documentElement.setAttribute(\"data-runtime\", mode);\n    if (mode === \"server\") {\n      if (sessionToken()) { $(\"loginGate\").classList.add(\"hidden\"); enterApp(); }\n      else showLogin();\n      return;\n    }\n    if (isAuthed()) {\n      $(\"loginGate\").classList.add(\"hidden\");\n      enterApp();\n    } else {\n      showLogin();\n      updateLockUi();\n      try { sessionStorage.removeItem(\"wb_hub_auth\"); } catch (e) {}\n    }\n  });\n}\nfunction enterApp() {\n  loadState();\n  state.demo = buildDemoData();\n  setupPoll();\n  refreshAll();\n  fetchAll();\n  if (RUNTIME.mode === \"server\") { pullServerState(); mzyFetchAllAux(true); }\n  else if (syncAutoOn() && syncReady()) pullRemote({ silent: true });\n}\n\n/* ---------- 后端模式数据流（CF Worker + D1） ---------- */\nfunction pullServerState() {\n  return apiFetch(\"api/state\").then(function (r) { return r.json(); }).then(function (j) {\n    if (!j || j.empty) { pushServerState(true); return; }\n    applyingRemote = true;\n    if (j.config) state.config = mergeConfig(j.config);\n    if (Array.isArray(j.todos)) state.todos = j.todos;\n    applyingRemote = false;\n    saveConfig(); saveTodos();\n    refreshAll();\n    fetchAll();\n  }).catch(function (e) {\n    if (e.message !== \"unauthorized\") showToast(\"云端数据拉取失败：\" + e.message, \"err\");\n  });\n}\nfunction pushServerState(silent) {\n  if (!sessionToken()) return Promise.resolve(false);\n  return apiFetch(\"api/state\", { method: \"PUT\", body: JSON.stringify({ config: state.config, todos: state.todos }) })\n    .then(function (r) { return r.json(); })\n    .then(function (j) {\n      if (!silent) showToast(\"已保存到云端 D1（含各服务 API 配置）\", \"good\");\n      return true;\n    })\n    .catch(function (e) {\n      if (e.message !== \"unauthorized\" && !silent) showToast(\"云端保存失败：\" + e.message, \"err\");\n      return false;\n    });\n}\n\n/* ---------- 初始化 ---------- */\ndocument.addEventListener(\"DOMContentLoaded\", boot);\n</script>\n</body>\n</html>\n";

/* ===================== 后端：API 模块 + D1 数据层 + 集中网关 ===================== */
const LOGIN_CFG = {"USER": "maoxinhe", "SALT": "wb-hub-2026-v1", "PASS_SHA256": "12f0a1de9d4b255513f110f71a7be27f7dcc191e2a0d2f38d1ceb8052a7e050c"};
const JSONH = { "content-type": "application/json;charset=UTF-8" };

function json(data, status) {
  return new Response(JSON.stringify(data), { status: status || 200, headers: { ...JSONH, "cache-control": "no-store" } });
}
async function sha256Hex(s) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, "0")).join("");
}
let schemaReady = false;
async function ensureSchema(db) {
  if (schemaReady) return;
  await db.batch([
    db.prepare("CREATE TABLE IF NOT EXISTS state (key TEXT PRIMARY KEY, value TEXT NOT NULL, updated_at TEXT NOT NULL)"),
    db.prepare("CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, name TEXT, url TEXT, base_url TEXT, auth_type TEXT, token TEXT, header_name TEXT, mapping TEXT, enabled INTEGER DEFAULT 1, updated_at TEXT)"),
    db.prepare("CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, created_at TEXT NOT NULL, expires_at TEXT NOT NULL)")
  ]);
  schemaReady = true;
}
async function getUser(request, db) {
  const m = (request.headers.get("Authorization") || "").match(/^Bearer (.+)$/);
  if (!m) return null;
  const row = await db.prepare("SELECT token FROM sessions WHERE token = ? AND expires_at > ?").bind(m[1], new Date().toISOString()).first();
  return row ? (LOGIN_CFG.USER || "admin") : null;
}
function newToken() {
  const a = new Uint8Array(24);
  crypto.getRandomValues(a);
  return [...a].map(b => b.toString(16).padStart(2, "0")).join("");
}
function timeoutSignal(ms) {
  const ctrl = new AbortController();
  setTimeout(() => ctrl.abort(), ms);
  return ctrl.signal;
}

/* ---- 登录 / 会话 ---- */
async function handleLogin(request, db) {
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: "请求体必须是 JSON" }, 400); }
  const user = String(body.user || ""), pass = String(body.pass || "");
  const ok = user === LOGIN_CFG.USER && pass.length > 0 && (await sha256Hex(LOGIN_CFG.SALT + pass)) === LOGIN_CFG.PASS_SHA256;
  if (!ok) return json({ error: "账号或密码错误" }, 401);
  const nowISO = new Date().toISOString();
  const expISO = new Date(Date.now() + 7 * 86400e3).toISOString();
  const token = newToken();
  await db.prepare("DELETE FROM sessions WHERE expires_at < ?").bind(nowISO).run();
  await db.prepare("INSERT INTO sessions (token, created_at, expires_at) VALUES (?, ?, ?)").bind(token, nowISO, expISO).run();
  return json({ token, user: LOGIN_CFG.USER, expiresAt: expISO });
}

/* ---- 工作台数据（配置 + 待办，存 D1 state 表） ---- */
async function getState(db) {
  const row = await db.prepare("SELECT value, updated_at FROM state WHERE key = 'main'").first();
  if (!row) return json({ empty: true });
  return new Response(row.value, { headers: { ...JSONH, "cache-control": "no-store", "x-updated-at": row.updated_at } });
}
async function putState(request, db) {
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: "请求体必须是 JSON" }, 400); }
  if (!body || !body.config || !Array.isArray(body.config.services)) return json({ error: "缺少 config 字段" }, 400);
  const now = new Date().toISOString();
  const todos = Array.isArray(body.todos) ? body.todos : [];
  const payload = JSON.stringify({ type: "wb-hub-state", version: 4, config: body.config, todos, savedAt: now });
  await db.prepare("INSERT INTO state (key, value, updated_at) VALUES ('main', ?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at")
    .bind(payload, now).run();
  /* 同步写 services 表 → 供网关集中调用（Token 存服务端，前端不接触） */
  const stmts = [];
  for (const s of body.config.services) {
    stmts.push(db.prepare(
      "INSERT INTO services (id, name, url, base_url, auth_type, token, header_name, mapping, enabled, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
      "ON CONFLICT(id) DO UPDATE SET name=excluded.name, url=excluded.url, base_url=excluded.base_url, auth_type=excluded.auth_type, token=excluded.token, header_name=excluded.header_name, mapping=excluded.mapping, enabled=excluded.enabled, updated_at=excluded.updated_at"
    ).bind(
      String(s.id), String(s.name || s.id), String(s.url || ""), String(s.baseUrl || ""),
      String(s.authType || "none"), String(s.token || ""), String(s.headerName || "X-API-Key"),
      JSON.stringify(s.advanced || {}), s.enabled ? 1 : 0, now
    ));
  }
  if (stmts.length) await db.batch(stmts);
  return json({ ok: true, savedAt: now });
}

/* ---- 集中网关：/api/proxy/<服务id>[/<子路径>] → 转发到各服务真实 API ---- */
async function handleProxy(request, db, url) {
  const m = url.pathname.match(/^\/api\/proxy\/([^/]+)(\/.*)?$/);
  if (!m) return json({ error: "not found" }, 404);
  const id = decodeURIComponent(m[1]);
  const sub = m[2] || "";
  const svc = await db.prepare("SELECT * FROM services WHERE id = ?").bind(id).first();
  if (!svc) return json({ error: `服务 "${id}" 不存在` }, 404);
  if (!svc.base_url) return json({ error: `服务 "${id}" 尚未配置 API 地址，请在工作台设置中保存` }, 404);
  let target;
  try { target = new URL(svc.base_url); } catch (e) { return json({ error: "该服务的 API 地址无效" }, 500); }
  if (sub) target.pathname = target.pathname.replace(/\/$/, "") + sub;
  target.search = url.search;
  const headers = {};
  if (svc.auth_type === "bearer" && svc.token) headers["Authorization"] = "Bearer " + svc.token;
  if (svc.auth_type === "header" && svc.token) headers[svc.header_name || "X-API-Key"] = svc.token;
  const ct = request.headers.get("content-type");
  if (ct) headers["content-type"] = ct;  // 透传 Content-Type：写接口（POST/PUT）要求 application/json
  const init = { method: request.method, headers, signal: timeoutSignal(12000) };
  if (request.method !== "GET" && request.method !== "HEAD") init.body = await request.text();
  try {
    const resp = await fetch(target.toString(), init);
    return new Response(resp.body, {
      status: resp.status,
      headers: { "content-type": resp.headers.get("content-type") || "application/json", "cache-control": "no-store", "x-proxied-by": "service-hub-gateway" }
    });
  } catch (e) {
    return json({ error: (e.name === "AbortError" ? "上游请求超时（12s）" : e.message) }, 502);
  }
}

/* ---- 连接测试：用表单当前值直接转发（不落库） ---- */
async function handleProxyTest(request) {
  let body;
  try { body = await request.json(); } catch (e) { return json({ error: "请求体必须是 JSON" }, 400); }
  const s = body.service || {};
  if (!s.baseUrl) return json({ error: "缺少 baseUrl" }, 400);
  const headers = {};
  if (s.authType === "bearer" && s.token) headers["Authorization"] = "Bearer " + s.token;
  if (s.authType === "header" && s.token) headers[s.headerName || "X-API-Key"] = s.token;
  try {
    const resp = await fetch(s.baseUrl, { headers, signal: timeoutSignal(12000) });
    const text = await resp.text();
    if (!resp.ok) return json({ error: `目标服务返回 HTTP ${resp.status}`, body: text.slice(0, 500) }, 502);
    try { return json(JSON.parse(text)); } catch (e) { return json({ error: "目标未返回有效 JSON", body: text.slice(0, 500) }); }
  } catch (e) {
    return json({ error: (e.name === "AbortError" ? "请求超时（12s）" : e.message) }, 502);
  }
}

/* ---- 路由入口 ---- */
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    try {
      if (url.pathname === "/" || url.pathname === "/index.html") {
        return new Response(HTML, { headers: { "content-type": "text/html;charset=UTF-8", "cache-control": "public, max-age=300", "x-content-type-options": "nosniff", "referrer-policy": "no-referrer", "x-frame-options": "SAMEORIGIN" } });
      }
      if (!url.pathname.startsWith("/api/")) return json({ error: "not found" }, 404);
      if (!env.DB) {
        if (url.pathname === "/api/health") return json({ ok: true, mode: "no-db" });
        return json({ error: "D1 数据库未绑定：Workers → Settings → Bindings 添加 D1 绑定，变量名 DB" }, 503);
      }
      await ensureSchema(env.DB);
      if (url.pathname === "/api/health") return json({ ok: true, mode: "server", time: new Date().toISOString() });
      if (url.pathname === "/api/auth/login" && request.method === "POST") return handleLogin(request, env.DB);

      const user = await getUser(request, env.DB);
      if (!user) return json({ error: "unauthorized" }, 401);

      if (url.pathname === "/api/auth/me") return json({ user });
      if (url.pathname === "/api/auth/logout" && request.method === "POST") {
        const m = (request.headers.get("Authorization") || "").match(/^Bearer (.+)$/);
        if (m) await env.DB.prepare("DELETE FROM sessions WHERE token = ?").bind(m[1]).run();
        return json({ ok: true });
      }
      if (url.pathname === "/api/state" && request.method === "GET") return getState(env.DB);
      if (url.pathname === "/api/state" && request.method === "PUT") return putState(request, env.DB);
      if (url.pathname === "/api/proxy-test" && request.method === "POST") return handleProxyTest(request);
      if (url.pathname.startsWith("/api/proxy/")) return handleProxy(request, env.DB, url);
      return json({ error: "not found" }, 404);
    } catch (e) {
      return json({ error: (e && e.message) || "internal error" }, 500);
    }
  }
};
